export function errorDetails(error) {
  const name = error?.name || 'Error';
  const message = error?.message || '';
  return { name, message };
}

export function friendlyError(error) {
  const { name, message } = errorDetails(error);
  const value = `${name} ${message}`.toLowerCase();
  if (/overconstrained|notfound/.test(value)) {
    return {
      title: '未找到可用的摄像头',
      message: 'Safari 无法打开后置摄像头。请关闭占用相机的 App，确认网站相机权限后点“重新尝试”。'
    };
  }
  if (/notallowed|permission|denied|摄像头/.test(value)) {
    return {
      title: '摄像头权限未开启',
      message: '请在 Safari 地址栏左侧的页面设置中允许“相机”，然后点“重新尝试”。'
    };
  }
  if (/indexeddb|database|storage|quota|opfs|file system/.test(value)) {
    return {
      title: '手机存储暂时不可用',
      message: '请退出无痕浏览，确认手机有可用空间，然后点“重新尝试”。'
    };
  }
  if (/offer|control code|session uuid|json|base64/.test(value)) {
    return {
      title: '会话二维码无效',
      message: '请回到 Mac 停止当前会话，重新选择“发送到手机”并扫描新二维码。'
    };
  }
  if (/webassembly|wasm|raptorq|bigint/.test(value)) {
    return {
      title: '手机浏览器不支持解码器',
      message: '请更新 iOS 后使用 Safari 重新打开二维码。'
    };
  }
  const detail = message || name || '未知错误';
  return { title: '接收初始化失败', message: `${detail}。请点“重新尝试”；如仍失败，请下载诊断记录。` };
}
