import { crc32c } from './crc32c.js';
import {
  concatBytes,
  readUint16BE,
  readUint32BE
} from './bytes.js';
import {
  OPTICAL_HEADER_LENGTH,
  OPTICAL_MAGIC,
  PROTOCOL_VERSION
} from './constants.js';

const SYMBOL_BATCH_HEADER_LENGTH = 2;
const SYMBOL_BATCH_ENTRY_HEADER_LENGTH = 6;

function uint16BE(value) {
  const result = new Uint8Array(2);
  new DataView(result.buffer).setUint16(0, value, false);
  return result;
}

function uint32BE(value) {
  const result = new Uint8Array(4);
  new DataView(result.buffer).setUint32(0, value, false);
  return result;
}

function uuidFromBytes(bytes) {
  const hex = Array.from(bytes, (value) => value.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`.toUpperCase();
}

export function decodeOpticalFrame(data) {
  if (data.length < OPTICAL_HEADER_LENGTH + 4) throw new Error('Optical frame is truncated');
  if (readUint32BE(data, 0) !== OPTICAL_MAGIC || readUint16BE(data, 4) !== PROTOCOL_VERSION) {
    throw new Error('Optical frame header is invalid');
  }
  if (crc32c(data.slice(0, 44)) !== readUint32BE(data, 44)) {
    throw new Error('Optical frame header checksum failed');
  }
  const payloadLength = readUint32BE(data, 40);
  const payloadEnd = OPTICAL_HEADER_LENGTH + payloadLength;
  if (payloadEnd + 4 > data.length) throw new Error('Optical frame payload is truncated');
  const payload = data.slice(OPTICAL_HEADER_LENGTH, payloadEnd);
  if (crc32c(payload) !== readUint32BE(data, payloadEnd)) {
    throw new Error('Optical frame payload checksum failed');
  }
  return {
    sessionID: uuidFromBytes(data.slice(8, 24)),
    profileID: data[6],
    flags: data[7],
    generationID: readUint32BE(data, 24),
    symbolID: readUint32BE(data, 28),
    generationLength: readUint32BE(data, 32),
    fragmentIndex: readUint16BE(data, 36),
    fragmentCount: readUint16BE(data, 38),
    payload
  };
}

export function encodeSymbolBatch(entries) {
  if (!Array.isArray(entries) || entries.length < 2 || entries.length > 0xffff) {
    throw new Error('A symbol batch must contain at least two entries');
  }
  const firstSymbolID = entries[0]?.symbolID;
  const parts = [uint16BE(entries.length)];
  for (let index = 0; index < entries.length; index += 1) {
    const entry = entries[index];
    const expectedID = firstSymbolID + index;
    if (!Number.isSafeInteger(entry?.symbolID)
        || entry.symbolID < 0
        || entry.symbolID > 0xffff_ffff
        || expectedID > 0xffff_ffff
        || entry.symbolID !== expectedID) {
      throw new Error('Symbol batch IDs must be contiguous');
    }
    if (!(entry.packet instanceof Uint8Array)
        || entry.packet.length === 0
        || entry.packet.length > 0xffff) {
      throw new Error('Symbol batch packet length is invalid');
    }
    parts.push(uint32BE(entry.symbolID), uint16BE(entry.packet.length), entry.packet);
  }
  return concatBytes(...parts);
}

export function decodeSymbolBatch(payload) {
  if (!(payload instanceof Uint8Array) || payload.length < SYMBOL_BATCH_HEADER_LENGTH) {
    throw new Error('Symbol batch is truncated');
  }
  const count = readUint16BE(payload, 0);
  if (count < 2) throw new Error('Invalid symbol batch count');
  const entries = [];
  let offset = SYMBOL_BATCH_HEADER_LENGTH;
  let firstSymbolID;
  for (let index = 0; index < count; index += 1) {
    if (offset + SYMBOL_BATCH_ENTRY_HEADER_LENGTH > payload.length) {
      throw new Error('Truncated symbol batch entry');
    }
    const symbolID = readUint32BE(payload, offset);
    const packetLength = readUint16BE(payload, offset + 4);
    offset += SYMBOL_BATCH_ENTRY_HEADER_LENGTH;
    const packetEnd = offset + packetLength;
    if (packetLength === 0 || packetEnd > payload.length) {
      throw new Error('Truncated symbol batch packet');
    }
    firstSymbolID ??= symbolID;
    if (firstSymbolID + index > 0xffff_ffff || symbolID !== firstSymbolID + index) {
      throw new Error('Symbol batch IDs must be contiguous');
    }
    entries.push({ symbolID, packet: payload.slice(offset, packetEnd) });
    offset = packetEnd;
  }
  if (offset !== payload.length) throw new Error('Symbol batch has trailing bytes');
  return entries;
}

export class SymbolAssembler {
  constructor() {
    this.fragments = new Map();
  }

  add(frame) {
    if (frame.fragmentCount === 0 || frame.fragmentCount > 256 || frame.fragmentIndex >= frame.fragmentCount) {
      throw new Error('Optical symbol fragment metadata is invalid');
    }
    const key = `${frame.generationID}:${frame.symbolID}`;
    let entry = this.fragments.get(key);
    if (!entry) {
      entry = { expected: frame.fragmentCount, parts: new Map() };
      this.fragments.set(key, entry);
    }
    entry.parts.set(frame.fragmentIndex, frame.payload);
    if (entry.parts.size !== entry.expected) return undefined;
    const parts = [];
    for (let index = 0; index < entry.expected; index += 1) {
      const part = entry.parts.get(index);
      if (!part) return undefined;
      parts.push(part);
    }
    this.fragments.delete(key);
    return concatBytes(...parts);
  }

  reset() {
    this.fragments.clear();
  }
}
