import { sha256 } from '@noble/hashes/sha256';
import { equalBytes } from './bytes.js';
import { GENERATION_SIZE } from './constants.js';

const DATABASE_NAME = 'OptiLinkWebReceiver';
const STORE_NAME = 'sessions';
const CHUNK_STORE_NAME = 'fileChunks';
const DATABASE_VERSION = 2;

function openDatabase() {
  return new Promise((resolve, reject) => {
    if (!globalThis.indexedDB) {
      reject(new Error('IndexedDB is unavailable'));
      return;
    }
    const request = indexedDB.open(DATABASE_NAME, DATABASE_VERSION);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(STORE_NAME)) {
        request.result.createObjectStore(STORE_NAME, { keyPath: 'sessionID' });
      }
      if (!request.result.objectStoreNames.contains(CHUNK_STORE_NAME)) {
        const chunks = request.result.createObjectStore(CHUNK_STORE_NAME, {
          keyPath: ['sessionID', 'generationID']
        });
        chunks.createIndex('sessionID', 'sessionID', { unique: false });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('Unable to open receiver database'));
  });
}

function transactionRequest(storeName, mode, operation) {
  return openDatabase().then((database) => new Promise((resolve, reject) => {
    const transaction = database.transaction(storeName, mode);
    const store = transaction.objectStore(storeName);
    const request = operation(store);
    let result;
    let settled = false;
    const rejectOnce = (error) => {
      if (settled) return;
      settled = true;
      database.close();
      reject(error);
    };
    request.onsuccess = () => {
      result = request.result;
    };
    request.onerror = () => rejectOnce(
      request.error ?? new Error('Receiver database operation failed')
    );
    transaction.oncomplete = () => {
      if (settled) return;
      settled = true;
      database.close();
      resolve(result);
    };
    transaction.onerror = () => rejectOnce(
      transaction.error ?? new Error('Receiver database transaction failed')
    );
    transaction.onabort = () => rejectOnce(
      transaction.error ?? new Error('Receiver database transaction was aborted')
    );
  }));
}

function deleteSessionChunks(sessionID) {
  return openDatabase().then((database) => new Promise((resolve, reject) => {
    const transaction = database.transaction(CHUNK_STORE_NAME, 'readwrite');
    const store = transaction.objectStore(CHUNK_STORE_NAME);
    const request = store.index('sessionID').openKeyCursor(IDBKeyRange.only(sessionID));
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) return;
      store.delete(cursor.primaryKey);
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error('Unable to clear receiver chunks'));
    transaction.oncomplete = () => {
      database.close();
      resolve();
    };
    transaction.onerror = () => {
      database.close();
      reject(transaction.error ?? new Error('Unable to clear receiver chunks'));
    };
  }));
}

export class BrowserSessionStore {
  constructor(sessionID) {
    this.sessionID = sessionID;
    this.fileHandle = undefined;
    this.fileSize = 0;
    this.storageMode = 'indexeddb';
    this.opfsError = undefined;
    this.initialMetadata = undefined;
  }

  async initialize() {
    // IndexedDB is the compatibility baseline and also stores session metadata.
    this.initialMetadata = await transactionRequest(
      STORE_NAME,
      'readonly',
      (store) => store.get(this.sessionID)
    );
    try {
      await navigator.storage?.persist?.();
    } catch {
      // Persistence is best effort.
    }
    const requiredMode = this.initialMetadata?.storageMode;
    if (requiredMode === 'indexeddb') return;
    if (!navigator.storage?.getDirectory) {
      if (requiredMode === 'opfs') {
        throw new Error('The OPFS storage used by this session is unavailable');
      }
      return;
    }
    try {
      const root = await navigator.storage.getDirectory();
      const optiLink = await root.getDirectoryHandle('OptiLink', { create: true });
      const sessions = await optiLink.getDirectoryHandle('Sessions', { create: true });
      const session = await sessions.getDirectoryHandle(this.sessionID, { create: true });
      this.fileHandle = await session.getFileHandle('received.partial', { create: true });
      this.storageMode = 'opfs';
    } catch (error) {
      if (requiredMode === 'opfs') {
        throw new Error('The OPFS storage used by this session is unavailable');
      }
      // Safari may expose OPFS but reject it in private browsing or after a storage failure.
      this.opfsError = error;
      this.fileHandle = undefined;
      this.storageMode = 'indexeddb';
    }
  }

  async loadMetadata() {
    const metadata = this.initialMetadata ?? await transactionRequest(
      STORE_NAME,
      'readonly',
      (store) => store.get(this.sessionID)
    );
    this.fileSize = metadata?.manifest?.fileSize ?? this.fileSize;
    return metadata;
  }

  saveMetadata(metadata) {
    return transactionRequest(STORE_NAME, 'readwrite', (store) => store.put({
      ...metadata,
      sessionID: this.sessionID,
      storageMode: this.storageMode,
      updatedAt: Date.now()
    }));
  }

  async preparePartialFile(size, preserveExisting = false) {
    this.fileSize = Number(size);
    if (this.storageMode === 'opfs') {
      this.ensureFileHandle();
      if (preserveExisting) return;
      const writable = await this.fileHandle.createWritable({ keepExistingData: true });
      await writable.truncate(size);
      await writable.close();
      return;
    }
    if (!preserveExisting) await deleteSessionChunks(this.sessionID);
  }

  async writeGeneration(data, generationID) {
    if (this.storageMode === 'opfs') {
      this.ensureFileHandle();
      const writable = await this.fileHandle.createWritable({ keepExistingData: true });
      await writable.write({
        type: 'write',
        position: generationID * GENERATION_SIZE,
        data
      });
      await writable.close();
      return;
    }
    await transactionRequest(CHUNK_STORE_NAME, 'readwrite', (store) => store.put({
      sessionID: this.sessionID,
      generationID,
      data: new Uint8Array(data)
    }));
  }

  async file() {
    if (this.storageMode === 'opfs') {
      this.ensureFileHandle();
      return this.fileHandle.getFile();
    }
    const generationCount = Math.ceil(this.fileSize / GENERATION_SIZE);
    const parts = [];
    for (let generationID = 0; generationID < generationCount; generationID += 1) {
      const record = await this.loadChunk(generationID);
      if (!record) throw new Error(`Stored generation ${generationID + 1} is unavailable`);
      parts.push(new Uint8Array(record.data));
    }
    return new Blob(parts, { type: 'application/zip' });
  }

  async sha256() {
    const file = await this.file();
    const hasher = sha256.create();
    const reader = file.stream().getReader();
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      hasher.update(value);
    }
    return hasher.digest();
  }

  async generationHash(generationID, generationSize = GENERATION_SIZE) {
    if (this.storageMode === 'indexeddb') {
      const record = await this.loadChunk(generationID);
      return sha256(record ? new Uint8Array(record.data) : new Uint8Array());
    }
    const file = await this.file();
    const start = generationID * generationSize;
    const data = new Uint8Array(await file.slice(start, start + generationSize).arrayBuffer());
    return sha256(data);
  }

  async mismatchedGenerations(manifest) {
    const mismatched = [];
    for (let index = 0; index < manifest.generationCount; index += 1) {
      const digest = await this.generationHash(index, manifest.generationSize);
      if (!equalBytes(digest, manifest.generationSHA256Bytes[index])) {
        mismatched.push(index + 1);
      }
    }
    return mismatched;
  }

  async download(fileName) {
    const file = await this.file();
    const namedFile = new File([file], sanitizeFileName(fileName), { type: 'application/zip' });
    if (navigator.share && navigator.canShare?.({ files: [namedFile] })) {
      await navigator.share({ files: [namedFile], title: namedFile.name });
      return;
    }
    const url = URL.createObjectURL(namedFile);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = sanitizeFileName(fileName);
    anchor.style.display = 'none';
    document.body.append(anchor);
    anchor.click();
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60_000);
  }

  ensureFileHandle() {
    if (!this.fileHandle) throw new Error('Browser file storage is not initialized');
  }

  loadChunk(generationID) {
    return transactionRequest(CHUNK_STORE_NAME, 'readonly', (store) => store.get([
      this.sessionID,
      generationID
    ]));
  }
}

function sanitizeFileName(value) {
  const name = value.split(/[\\/]/).pop()?.trim() || 'received.zip';
  return name.toLowerCase().endsWith('.zip') ? name : `${name}.zip`;
}
