let engine;
let decoder;
let answerCode;
let cameraStarted = false;
let processingFrame = false;
let feedbackTransitionBusy = false;
let feedbackCodeReady = false;
let lastReceiverPhase = 'handshake';
let completionAcknowledged = false;
let paused = false;
let frameLoopHandle;
let wakeLock;
let resumeCameraAfterVisibility = false;
let cameraStartPromise;
let cameraOperationEpoch = 0;
let visibilityEpoch = 0;
let lastControlScanAt = 0;
let lastOpticalSuccessAt = 0;
let lastOpticalDecodeAt = 0;
let calibrationStableFrames = 0;
let calibrationLocked = false;
let lastProfileID = 'S0';
let lastGuidanceDiagnosticAt = 0;

const CALIBRATION_LOCK_FRAMES = 3;
const CALIBRATION_MIN_MODULE_PIXELS = 2.8;
const CALIBRATION_MIN_AREA_FRACTION = 0.08;

function formatBytes(value) {
  if (!value) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  const index = Math.min(units.length - 1, Math.floor(Math.log(value) / Math.log(1024)));
  return `${(value / (1024 ** index)).toFixed(index === 0 ? 0 : 2)} ${units[index]}`;
}

function statusText(snapshot) {
  if (snapshot.state === 'failed') {
    return ['接收失败', snapshot.failureMessage ?? '请重新开始会话'];
  }
  if (snapshot.state === 'verifying') {
    return ['正在校验完整文件', '执行流式 SHA-256，请不要关闭页面'];
  }
  if (snapshot.receiverPhase === 'handshake') {
    return [
      snapshot.state === 'complete' ? '正在恢复已完成会话' : '等待 Mac 确认',
      '将 iPhone 屏幕上的回答二维码对准 Mac 摄像头'
    ];
  }
  if (snapshot.receiverPhase === 'feedbackReady') {
    if (snapshot.state === 'complete') {
      return ['ZIP 已完整接收', '请先将此二维码给 Mac 扫描，再保存文件'];
    }
    return [`第 ${snapshot.roundID} 轮接收结束`, '请翻转 iPhone，将此二维码对准 Mac 摄像头'];
  }
  if (snapshot.receiverPhase === 'receiving') {
    const generation = snapshot.roundGenerationID || snapshot.metrics.generationID;
    return [
      snapshot.manifest ? `第 ${Math.max(1, snapshot.roundID + 1)} 轮接收中` : '正在接收加密清单',
      `保持手机背面对准 Mac 屏幕${generation ? ` · Generation ${generation}` : ''}`
    ];
  }
  switch (snapshot.state) {
  case 'keyExchange': return ['等待 Mac 确认', '将 iPhone 屏幕上的回答二维码对准 Mac 摄像头'];
  case 'calibrating': return ['安全链路已建立', '正在识别 Mac 光学网格'];
  case 'transferring': return [snapshot.manifest ? `正在接收 ${snapshot.manifest.fileName}` : '正在接收加密清单', '请固定两台设备的位置'];
  case 'reacquiring': return ['光学链路暂停', '重新对准 Mac 屏幕，系统会自动恢复'];
  case 'complete': return ['ZIP 已完整接收', '校验通过，可以保存到“文件”'];
  default: return ['准备接收', '按提示在后置摄像头与反馈二维码之间翻转手机'];
  }
}

function isLandscape() {
  return window.innerWidth >= window.innerHeight;
}

function resetCalibration() {
  calibrationStableFrames = 0;
  calibrationLocked = false;
  lastOpticalDecodeAt = 0;
}

function updateAlignment({ quality, title, detail }) {
  elements.alignmentCard.dataset.quality = quality;
  elements.alignmentTitle.textContent = title;
  elements.alignmentDetail.textContent = detail;
}

function geometryGuidance(geometry, success = false) {
  if (!isLandscape()) {
    return {
      quality: 'blocked',
      title: '请将 iPhone 横过来',
      detail: '保持后置摄像头朝向 Mac 屏幕'
    };
  }
  if (!geometry?.finderVisible || (geometry.candidateCount ?? 0) < 4) {
    return {
      quality: 'poor',
      title: `只找到 ${geometry?.candidateCount ?? 0}/4 个定位点`,
      detail: '后退少许，确保 Mac 屏幕四角都在取景框内'
    };
  }
  if ((geometry.modulePixels ?? 0) < CALIBRATION_MIN_MODULE_PIXELS) {
    return {
      quality: 'poor',
      title: `网格过小 · ${(geometry.modulePixels ?? 0).toFixed(1)} px/模块`,
      detail: '请靠近 Mac，让屏幕占据更多取景范围'
    };
  }
  if ((geometry.areaFraction ?? 0) < CALIBRATION_MIN_AREA_FRACTION) {
    return {
      quality: 'poor',
      title: `屏幕占比偏低 · ${Math.round((geometry.areaFraction ?? 0) * 100)}%`,
      detail: '请靠近 Mac，同时保持四个定位点完整可见'
    };
  }
  if (!success) {
    return {
      quality: 'fair',
      title: '四角已锁定，正在校正颜色',
      detail: '保持不动，并避免灯光反射到屏幕上'
    };
  }
  if (!calibrationLocked) {
    return {
      quality: 'fair',
      title: `校准中 ${calibrationStableFrames}/${CALIBRATION_LOCK_FRAMES}`,
      detail: `${geometry.modulePixels.toFixed(1)} px/模块 · 屏幕占比 ${Math.round(geometry.areaFraction * 100)}%`
    };
  }
  return {
    quality: 'good',
    title: '光学链路已锁定',
    detail: `${geometry.modulePixels.toFixed(1)} px/模块 · ${geometry.orientation}°${geometry.mirrored ? ' 镜像' : ''}`
  };
}

function renderSnapshot(snapshot) {
  const [status, detail] = statusText(snapshot);
  const receiving = snapshot.receiverPhase === 'receiving';
  const feedbackReady = snapshot.receiverPhase === 'feedbackReady';
  const phaseChanged = snapshot.receiverPhase !== lastReceiverPhase;
  const profileChanged = snapshot.profileID !== lastProfileID;
  if (feedbackReady && lastReceiverPhase !== 'feedbackReady') feedbackCodeReady = false;
  if (receiving && (phaseChanged || profileChanged)) resetCalibration();
  if (receiving) feedbackCodeReady = false;
  lastReceiverPhase = snapshot.receiverPhase;
  lastProfileID = snapshot.profileID;
  elements.shell.dataset.phase = snapshot.receiverPhase;
  elements.qrFrame.hidden = receiving || (feedbackReady && !feedbackCodeReady);
  elements.scanStage.hidden = !receiving;
  elements.rotatePrompt.hidden = !receiving || isLandscape();
  elements.status.textContent = status;
  elements.detail.textContent = detail;
  elements.state.textContent = snapshot.state.toUpperCase();
  elements.profile.textContent = snapshot.profileID;
  const roundStats = feedbackReady ? snapshot.lastRoundSummary : snapshot.currentRoundStats;
  const targetRank = roundStats?.sourceSymbolCount || 0;
  const rank = feedbackReady
    ? roundStats?.rankEnd ?? snapshot.metrics.receivedRank
    : snapshot.metrics.receivedRank;
  const visibleRoundID = roundStats?.roundID ?? snapshot.roundID;
  const visibleGenerationID = roundStats?.generationID ?? snapshot.roundGenerationID;
  elements.round.textContent = visibleRoundID > 0
    ? `第 ${visibleRoundID} 轮 · G${visibleGenerationID} · R${rank}${targetRank ? `/${targetRank}` : ''}`
    : '握手';
  elements.roundLabel.textContent = `第 ${Math.max(1, snapshot.roundID + 1)} 轮接收中`;
  elements.throughput.textContent = `${snapshot.throughputMbps.toFixed(2)} Mbps`;
  elements.progress.style.width = `${(snapshot.progressFraction * 100).toFixed(2)}%`;
  elements.received.textContent = snapshot.manifest
    ? `${formatBytes(snapshot.completedBytes)} / ${formatBytes(snapshot.manifest.fileSize)}`
    : '等待清单';
  const attempted = roundStats?.attemptedFrames ?? 0;
  const decoded = roundStats?.decodedFrames ?? 0;
  const successPercent = attempted > 0 ? Math.round(decoded * 100 / attempted) : 0;
  elements.frameStats.textContent = `${decoded} / ${attempted} · ${successPercent}%`;
  elements.rankStats.textContent = `${rank} / ${targetRank || '?'} · ${snapshot.targetFPS}fps`;
  elements.diagnosis.hidden = !snapshot.diagnosis;
  elements.diagnosis.textContent = snapshot.diagnosis ?? '';
  elements.diagnosticsButton.hidden = !engine;
  elements.downloadButton.hidden = snapshot.state !== 'complete'
    || (!feedbackReady && snapshot.receiverPhase !== 'complete')
    || (feedbackReady && (!feedbackCodeReady || !completionAcknowledged));
  elements.continueButton.textContent = snapshot.state === 'complete'
    ? 'Mac 已扫描，显示保存按钮'
    : 'Mac 已扫描，继续下一轮';
  elements.continueButton.hidden = !feedbackReady
    || !feedbackCodeReady
    || snapshot.state === 'failed'
    || (snapshot.state === 'complete' && completionAcknowledged);
  elements.pauseButton.hidden = true;
  if (snapshot.state === 'complete' && feedbackReady) {
    stopCameraCapture();
  }
}

function decodeErrorCategory(error) {
  if (error?.category) return error.category;
  const value = `${error?.message ?? error}`.toLowerCase();
  if (value.includes('finder') || value.includes('visible')) return 'finder';
  if (value.includes('geometry') || value.includes('perspective')) return 'geometry';
  if (value.includes('checksum') || value.includes('crc') || value.includes('reed')) return 'checksum';
  if (value.includes('profile')) return 'profile';
  return 'other';
}

async function renderQR(code) {
  const cssWidth = Math.min(430, Math.max(280, window.innerWidth * 0.76)) - 26;
  const renderWidth = Math.min(1_024, Math.max(600, Math.round(cssWidth * window.devicePixelRatio)));
  await QRCode.toCanvas(elements.qr, code, {
    errorCorrectionLevel: 'M',
    margin: 2,
    width: renderWidth,
    color: { dark: '#071012', light: '#f3f0e7' }
  });
}

async function requestWakeLock() {
  try {
    wakeLock = await navigator.wakeLock?.request('screen');
  } catch {
    wakeLock = undefined;
  }
}

function fail(error) {
  console.error(error);
  const details = errorDetails(error);
  engine?.recordDiagnostic('ui-failure', {
    errorName: details.name,
    errorMessage: details.message,
    camera: decoder?.cameraDiagnostics?.()
  });
  const friendly = friendlyError(error);
  elements.errorTitle.textContent = friendly.title;
  elements.errorText.textContent = friendly.message;
  elements.errorPanel.hidden = false;
  elements.status.textContent = friendly.title;
  stopCameraCapture();
}

async function processCameraFrame() {
  if (!cameraStarted || processingFrame || document.hidden || !engine) return;
  if (!decoder.isCameraActive()) {
    stopFrameLoop();
    cameraStarted = false;
    elements.startButton.textContent = '继续后置摄像头';
    elements.startButton.hidden = false;
    elements.status.textContent = '摄像头已停止，请点击继续';
    return;
  }
  processingFrame = true;
  try {
    const snapshot = engine.snapshot();
    const now = performance.now();
    const controlInterval = engine.handshakeComplete ? 350 : 160;
    const controlDue = now - lastControlScanAt >= controlInterval;
    const opticalDue = engine.handshakeComplete
      && snapshot.receiverPhase === 'receiving'
      && !paused
      && now - lastOpticalDecodeAt >= 1_000 / Math.max(1, snapshot.targetFPS);
    if (!controlDue && !opticalDue) return;
    const imageData = decoder.capture();
    if (!engine.handshakeComplete) {
      if (controlDue) {
        const controlStartedAt = performance.now();
        lastControlScanAt = controlStartedAt;
        const code = decoder.scanControlCode(imageData);
        engine.recordControlScan({
          success: code?.startsWith('optilink1:') === true,
          latencyMilliseconds: performance.now() - controlStartedAt
        });
        if (code?.startsWith('optilink1:')) {
          const accepted = await engine.acceptControl(decodeControlCode(code));
          if (accepted) lastOpticalSuccessAt = performance.now();
        }
      }
    } else if (snapshot.receiverPhase === 'receiving' && !paused) {
      if (controlDue) {
        const controlStartedAt = performance.now();
        lastControlScanAt = controlStartedAt;
        const code = decoder.scanControlCode(imageData);
        engine.recordControlScan({
          success: code?.startsWith('optilink1:') === true,
          latencyMilliseconds: performance.now() - controlStartedAt
        });
        if (code?.startsWith('optilink1:')) {
          const accepted = await engine.acceptControl(decodeControlCode(code));
          if (accepted && engine.snapshot().receiverPhase === 'feedbackReady') {
            await enterFeedbackPhase();
            return;
          }
        }
      }
      if (engine.snapshot().state === 'complete') return;
      if (!opticalDue) return;
      lastOpticalDecodeAt = now;
      if (!isLandscape()) {
        calibrationStableFrames = 0;
        calibrationLocked = false;
        updateAlignment(geometryGuidance(undefined));
        if (now - lastGuidanceDiagnosticAt >= 2_000) {
          engine.recordDiagnostic('orientation-blocked', {
            viewport: { width: window.innerWidth, height: window.innerHeight },
            camera: decoder.cameraDiagnostics()
          });
          lastGuidanceDiagnosticAt = now;
        }
        return;
      }
      const opticalStartedAt = performance.now();
      try {
        const result = decoder.decode(snapshot.profileID, imageData);
        const geometryReady = result.geometry.modulePixels >= CALIBRATION_MIN_MODULE_PIXELS
          && result.geometry.areaFraction >= CALIBRATION_MIN_AREA_FRACTION;
        calibrationStableFrames = geometryReady ? calibrationStableFrames + 1 : 0;
        calibrationLocked = calibrationStableFrames >= CALIBRATION_LOCK_FRAMES;
        updateAlignment(geometryGuidance(result.geometry, true));
        if (calibrationLocked) await engine.acceptFrame(result.frame);
        lastOpticalSuccessAt = performance.now();
        engine.recordDecode({
          success: true,
          latencyMilliseconds: performance.now() - opticalStartedAt,
          colorConfidence: result.colorConfidence,
          finderVisible: true,
          geometry: result.geometry
        });
        renderSnapshot(engine.snapshot());
      } catch (error) {
        if (engine.snapshot().state === 'failed') {
          await enterFeedbackPhase();
          return;
        }
        calibrationStableFrames = 0;
        calibrationLocked = false;
        const geometry = error?.diagnostics;
        const finderVisible = geometry?.finderVisible
          ?? performance.now() - lastOpticalSuccessAt <= 500;
        updateAlignment(geometryGuidance(geometry, false));
        engine.recordDecode({
          success: false,
          latencyMilliseconds: performance.now() - opticalStartedAt,
          colorConfidence: 0.5,
          finderVisible,
          errorCategory: decodeErrorCategory(error),
          errorMessage: error?.message ?? String(error),
          geometry
        });
        renderSnapshot(engine.snapshot());
      }
    }
  } catch (error) {
    if (error?.name !== 'InvalidStateError') console.debug('Camera frame skipped:', error);
  } finally {
    processingFrame = false;
  }
}

async function downloadDiagnostics() {
  if (!engine) return;
  const report = engine.diagnosticReport();
  const fileName = `OptiLink-diagnostics-${report.sessionID.slice(0, 8)}.json`;
  const file = new File(
    [JSON.stringify(report, null, 2)],
    fileName,
    { type: 'application/json' }
  );
  if (navigator.share && navigator.canShare?.({ files: [file] })) {
    await navigator.share({ files: [file], title: fileName });
    return;
  }
  const url = URL.createObjectURL(file);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  anchor.style.display = 'none';
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60_000);
}

function scheduleFrame() {
  if (!cameraStarted) return;
  if ('requestVideoFrameCallback' in HTMLVideoElement.prototype) {
    frameLoopHandle = elements.video.requestVideoFrameCallback(async () => {
      await processCameraFrame();
      scheduleFrame();
    });
  } else {
    frameLoopHandle = window.setTimeout(async () => {
      await processCameraFrame();
      scheduleFrame();
    }, 34);
  }
}

function stopFrameLoop() {
  if (!frameLoopHandle) return;
  if ('cancelVideoFrameCallback' in elements.video) {
    elements.video.cancelVideoFrameCallback(frameLoopHandle);
  } else {
    clearTimeout(frameLoopHandle);
  }
  frameLoopHandle = undefined;
}

function stopCameraCapture(invalidatePendingStart = true) {
  if (invalidatePendingStart) cameraOperationEpoch += 1;
  stopFrameLoop();
  decoder?.stopCamera();
  cameraStarted = false;
}

async function enterFeedbackPhase() {
  if (!engine?.handshakeComplete || feedbackTransitionBusy) return;
  feedbackTransitionBusy = true;
  try {
    feedbackCodeReady = false;
    resetCalibration();
    renderSnapshot(engine.snapshot());
    stopCameraCapture();
    const code = await engine.feedbackCode();
    await renderQR(code);
    feedbackCodeReady = true;
    renderSnapshot(engine.snapshot());
  } catch (error) {
    fail(error);
  } finally {
    feedbackTransitionBusy = false;
  }
}

function startCamera(showAnswer = true, resumeRound = false) {
  if (!engine || !decoder) return false;
  if (cameraStarted && decoder.isCameraActive()) return true;
  if (cameraStartPromise) return cameraStartPromise;
  if (cameraStarted) stopCameraCapture();
  const operationEpoch = ++cameraOperationEpoch;
  const operation = (async () => {
    elements.errorPanel.hidden = true;
    elements.status.textContent = '正在启动后置摄像头...';
    try {
      await engine.prepareDecoder();
      if (operationEpoch !== cameraOperationEpoch || document.hidden) return false;
      await decoder.startCamera();
      if (operationEpoch !== cameraOperationEpoch || document.hidden) {
        decoder.stopCamera();
        return false;
      }
      cameraStarted = true;
      resetCalibration();
      engine.recordDiagnostic('camera-started', decoder.cameraDiagnostics());
      if (resumeRound) {
        const resumed = await engine.resumeRoundReception();
        if (!resumed) {
          stopCameraCapture();
          return false;
        }
      }
      elements.blockingPanel.hidden = true;
      elements.startButton.hidden = true;
      await requestWakeLock();
      if (showAnswer && !engine.handshakeComplete && answerCode) await renderQR(answerCode);
      renderSnapshot(engine.snapshot());
      scheduleFrame();
      return true;
    } catch (error) {
      fail(error);
      return false;
    }
  })();
  cameraStartPromise = operation.finally(() => {
    cameraStartPromise = undefined;
  });
  return cameraStartPromise;
}

async function continueRound() {
  elements.continueButton.disabled = true;
  try {
    if (engine.snapshot().state === 'complete') {
      completionAcknowledged = true;
      renderSnapshot(engine.snapshot());
      elements.status.textContent = 'Mac 已确认完成';
      elements.detail.textContent = '现在可以保存经过 SHA-256 校验的 ZIP';
      return;
    }
    await startCamera(false, true);
  } catch (error) {
    fail(error);
  } finally {
    elements.continueButton.disabled = false;
  }
}

async function togglePause() {
  paused = !paused;
  elements.pauseButton.textContent = paused ? '继续' : '暂停';
  await engine.setPaused(paused);
}

async function initialize() {
  if (!window.isSecureContext) {
    throw new Error('摄像头模式必须通过 HTTPS 打开');
  }
  if (!new URLSearchParams(window.location.hash.slice(1)).has('offer')) {
    elements.status.textContent = '接收器已就绪';
    elements.detail.textContent = '请从 Mac 的“发送到手机”二维码进入会话';
    elements.blockingTitle.textContent = 'OptiLink 已准备好';
    elements.blockingDetail.textContent = '回到 Mac，选择“发送到手机”和 ZIP，然后用 iPhone 相机扫描 Mac 屏幕上的二维码。';
    elements.blockingNote.textContent = '无需填写网址，也无需安装 App。可通过 Safari 的“添加到主屏幕”保存此接收器。';
    elements.blockingStartButton.hidden = true;
    elements.startButton.hidden = true;
    return;
  }
  const { offer } = offerFromLocation();
  const store = new BrowserSessionStore(offer.sessionID);
  engine = new BrowserReceiverEngine(offer, store);
  decoder = new BrowserOpticalDecoder(elements.video);
  engine.addEventListener('update', (event) => {
    renderSnapshot(event.detail);
    if (event.detail.state === 'failed'
        && event.detail.receiverPhase === 'feedbackReady'
        && !feedbackCodeReady) {
      void enterFeedbackPhase();
    }
  });
  answerCode = await engine.initialize();
  elements.startButton.disabled = false;
  elements.blockingStartButton.disabled = false;
  const snapshot = engine.snapshot();
  if (snapshot.receiverPhase === 'feedbackReady' && answerCode) {
    await renderQR(answerCode);
    feedbackCodeReady = true;
  }
  renderSnapshot(snapshot);
  if (snapshot.receiverPhase === 'feedbackReady' || snapshot.receiverPhase === 'complete') {
    elements.blockingPanel.hidden = true;
    elements.startButton.hidden = true;
  }
}

elements.startButton.addEventListener('click', () => startCamera(true));
elements.blockingStartButton.addEventListener('click', () => startCamera(true));
elements.pauseButton.addEventListener('click', togglePause);
elements.continueButton.addEventListener('click', continueRound);
elements.downloadButton.addEventListener('click', async () => {
  try {
    await engine.download();
  } catch (error) {
    fail(error);
  }
});
elements.diagnosticsButton.addEventListener('click', () => downloadDiagnostics().catch(fail));
elements.errorDiagnosticsButton.addEventListener('click', () => downloadDiagnostics().catch(fail));
elements.retryButton.addEventListener('click', () => window.location.reload());

document.addEventListener('visibilitychange', async () => {
  if (!engine) return;
  const eventEpoch = ++visibilityEpoch;
  if (document.hidden) {
    resumeCameraAfterVisibility = cameraStarted || cameraStartPromise !== undefined;
    cameraOperationEpoch += 1;
    if (engine.handshakeComplete) await engine.setPaused(true, true);
    if (eventEpoch !== visibilityEpoch || !document.hidden) return;
    stopCameraCapture(false);
    await wakeLock?.release?.();
    wakeLock = undefined;
    return;
  }
  if (engine.handshakeComplete) await engine.setPaused(false, true);
  if (cameraStartPromise) await cameraStartPromise;
  if (eventEpoch !== visibilityEpoch || document.hidden) return;
  await requestWakeLock();
  if (eventEpoch !== visibilityEpoch || document.hidden) return;
  const snapshot = engine.snapshot();
  if (resumeCameraAfterVisibility
      && snapshot.receiverPhase !== 'feedbackReady'
      && !decoder.isCameraActive()) {
    await startCamera(!engine.handshakeComplete);
  }
  if (eventEpoch !== visibilityEpoch || document.hidden) return;
  resumeCameraAfterVisibility = false;
});

window.addEventListener('pagehide', () => {
  visibilityEpoch += 1;
  wakeLock?.release?.();
  stopCameraCapture();
});

window.addEventListener('resize', () => {
  if (!engine) return;
  const receiving = engine.snapshot().receiverPhase === 'receiving';
  elements.rotatePrompt.hidden = !receiving || isLandscape();
  if (receiving && !isLandscape()) updateAlignment(geometryGuidance(undefined));
});

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js').catch(console.debug));
}

initialize().catch(fail);
