import { sha256 } from '@noble/hashes/sha256';
import { base64ToBytes, bytesToBase64, equalBytes, textDecoder } from './bytes.js';
import {
  BROWSER_BATCH_CAPABILITY,
  BROWSER_RAPTORQ_SYMBOL_SIZE,
  BROWSER_SYMBOL_CAPABILITY,
  GENERATION_SIZE,
  LEGACY_BROWSER_RAPTORQ_SYMBOL_SIZE,
  LEGACY_BROWSER_SYMBOL_CAPABILITY,
  PROFILES,
  PROTOCOL_VERSION,
  RAPTORQ_SYMBOL_SIZE,
  OPTICAL_SYMBOL_BATCH_FLAG
} from './constants.js';
import { decodeSymbolBatch, SymbolAssembler } from './optical-frame.js';
import { BrowserSessionCipher, encodeControlCode } from './protocol.js';
import { BrowserRaptorQDecoder, initializeRaptorQ } from './raptorq-decoder.js';

class RetryableGenerationError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'RetryableGenerationError';
  }
}

const MAX_ENCRYPTED_GENERATION_LENGTH = 2 * 1_024 * 1_024;

function initialMetrics() {
  return {
    generationID: 0,
    receivedRank: 0,
    frameSuccessRate: 1,
    crcFailureRate: 0,
    shardLossRate: 0,
    decodeFPS: 0,
    decodeP95Milliseconds: 0,
    queueDepth: 0,
    colorConfidence: 1,
    finderVisible: true
  };
}

function manifestWithBytes(raw) {
  return {
    ...raw,
    fileSHA256Bytes: base64ToBytes(raw.fileSHA256),
    generationSHA256Bytes: raw.generationSHA256.map(base64ToBytes)
  };
}

function validateManifest(raw, sessionID) {
  const generationCount = Math.ceil(raw.fileSize / GENERATION_SIZE);
  const manifest = manifestWithBytes(raw);
  const valid = raw.protocolVersion === PROTOCOL_VERSION
    && String(raw.sessionID).toUpperCase() === sessionID.toUpperCase()
    && raw.fileSize > 0
    && raw.generationSize === GENERATION_SIZE
    && raw.generationCount === generationCount
    && raw.generationSHA256.length === generationCount
    && manifest.fileSHA256Bytes.length === 32
    && manifest.generationSHA256Bytes.every((digest) => digest.length === 32);
  if (!valid) throw new Error('Encrypted transfer manifest is invalid');
  return manifest;
}

export function parseRoundBoundaryDetail(detail) {
  const match = /^round-ended:(\d+):(\d+):(\d+)$/.exec(detail ?? '');
  if (!match) return undefined;
  return {
    roundID: Number(match[1]),
    generationID: Number(match[2]),
    nextSymbolID: Number(match[3])
  };
}

export function parseRoundReadyDetail(detail) {
  const match = /^round-ready:(\d+):(\d+)$/.exec(detail ?? '');
  if (!match) return undefined;
  return {
    roundID: Number(match[1]),
    generationID: Number(match[2])
  };
}

function percentile95(values) {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((left, right) => left - right);
  return sorted[Math.min(sorted.length - 1, Math.ceil(sorted.length * 0.95) - 1)];
}

function roundDiagnosis(summary) {
  if (!summary || summary.attemptedFrames === 0) return '未获取到相机帧，请确认 Safari 保持前台且摄像头仍在运行';
  if (summary.captureCoverage < 0.55) return '手机解码速度跟不上发送节奏，已使用更低帧率；请关闭低电量模式和其他高负载应用';
  if (summary.finderFailures > summary.attemptedFrames * 0.45) return '多数帧未找到完整网格，请让 Mac 屏幕占满取景框并保持正对';
  if (summary.geometryFailures > summary.attemptedFrames * 0.45 && summary.modulePixelsMinimum < 3) {
    return `网格模块最小仅 ${summary.modulePixelsMinimum.toFixed(1)} 像素，请横屏并靠近 Mac 屏幕`;
  }
  if (summary.geometryFailures > summary.attemptedFrames * 0.45) return '已找到定位标记，但四角透视不稳定；请完整拍到四角并减小夹角';
  if (summary.checksumFailures > summary.attemptedFrames * 0.25) return '网格已找到但数据误码较多，请提高屏幕亮度并避免反光或摩尔纹';
  if (summary.frameSuccessRate < 0.65) return '有效帧比例偏低，下一轮保持设备不动并降低环境光干扰';
  if (summary.rankGained === 0) return '识别到了帧但没有形成新的 RaptorQ symbol，请继续修复轮次';
  if (summary.rankDeficit > 0) return `本轮新增 ${summary.rankGained} 个 symbol，仍缺约 ${summary.rankDeficit} 个`;
  return '本轮识别稳定，等待 Mac 根据反馈进入下一步';
}

function makeRoundStats(roundID, generationID, rankStart) {
  return {
    roundID,
    generationID,
    startedAt: new Date().toISOString(),
    startedAtMonotonic: performance.now(),
    rankStart,
    sourceSymbolCount: 0,
    attemptedFrames: 0,
    decodedFrames: 0,
    uniqueFragments: 0,
    duplicateFragments: 0,
    completedSymbols: 0,
    controlScanAttempts: 0,
    controlScanSuccesses: 0,
    controlScanMilliseconds: 0,
    finderFailures: 0,
    geometryFailures: 0,
    checksumFailures: 0,
    profileFailures: 0,
    otherFailures: 0,
    latencySamples: [],
    geometrySamples: 0,
    candidateCountTotal: 0,
    candidateCountMaximum: 0,
    componentCountTotal: 0,
    areaFractionTotal: 0,
    modulePixelsTotal: 0,
    modulePixelsMinimum: Number.POSITIVE_INFINITY,
    orientationCounts: {},
    lastCorners: undefined,
    failureSamples: []
  };
}

function geometrySummary(stats) {
  const sampleCount = stats.geometrySamples;
  return {
    geometrySamples: sampleCount,
    candidateCountAverage: sampleCount > 0 ? stats.candidateCountTotal / sampleCount : 0,
    candidateCountMaximum: stats.candidateCountMaximum,
    componentCountAverage: sampleCount > 0 ? stats.componentCountTotal / sampleCount : 0,
    areaFractionAverage: sampleCount > 0 ? stats.areaFractionTotal / sampleCount : 0,
    modulePixelsAverage: sampleCount > 0 ? stats.modulePixelsTotal / sampleCount : 0,
    modulePixelsMinimum: Number.isFinite(stats.modulePixelsMinimum) ? stats.modulePixelsMinimum : 0,
    orientationCounts: { ...stats.orientationCounts },
    lastCorners: stats.lastCorners,
    failureSamples: [...stats.failureSamples]
  };
}

class BrowserAdaptationController {
  constructor(profileID = 'P0') {
    this.profileID = ['S0', 'P0', 'P1'].includes(profileID) ? profileID : 'P0';
    this.excellentWindows = 0;
    this.windowStartedAt = undefined;
  }

  evaluate(metrics, now = performance.now()) {
    if (!metrics.finderVisible) {
      this.excellentWindows = 0;
      this.windowStartedAt = undefined;
      return { profileID: this.profileID, shouldPause: true, reason: 'Finder lost' };
    }
    const profile = PROFILES.find((candidate) => candidate.id === this.profileID) ?? PROFILES[0];
    const frameBudget = 1000 / profile.fps;
    const degraded = metrics.frameSuccessRate < 0.90
      || metrics.queueDepth > 2
      || metrics.decodeP95Milliseconds > frameBudget * 0.8
      || metrics.colorConfidence < 0.70;
    if (degraded) {
      this.profileID = this.profileID === 'P1' ? 'P0' : 'S0';
      this.excellentWindows = 0;
      this.windowStartedAt = undefined;
      return { profileID: this.profileID, shouldPause: false, reason: 'Quality degraded' };
    }
    const excellent = metrics.frameSuccessRate > 0.98
      && metrics.shardLossRate < 0.05
      && metrics.decodeP95Milliseconds < frameBudget * 0.5
      && metrics.colorConfidence > 0.90;
    if (excellent && this.profileID !== 'P1') {
      if (this.windowStartedAt === undefined) {
        this.windowStartedAt = now;
      } else if (now - this.windowStartedAt >= 1000) {
        this.excellentWindows += 1;
        this.windowStartedAt = now;
      }
    } else if (!excellent) {
      this.excellentWindows = 0;
      this.windowStartedAt = undefined;
    }
    if (this.excellentWindows >= 5) {
      this.profileID = this.profileID === 'S0' ? 'P0' : 'P1';
      this.excellentWindows = 0;
      this.windowStartedAt = undefined;
      return { profileID: this.profileID, shouldPause: false, reason: 'Stable browser link' };
    }
    return { profileID: this.profileID, shouldPause: false, reason: 'Hold' };
  }
}

export class BrowserReceiverEngine extends EventTarget {
  constructor(offer, store) {
    super();
    this.offer = offer;
    this.store = store;
    this.state = 'pairing';
    this.profileID = offer.capabilities?.includes('S0') ? 'S0' : 'P0';
    this.symbolSize = offer.capabilities?.includes(BROWSER_SYMBOL_CAPABILITY)
      ? BROWSER_RAPTORQ_SYMBOL_SIZE
      : offer.capabilities?.includes(LEGACY_BROWSER_SYMBOL_CAPABILITY)
        ? LEGACY_BROWSER_RAPTORQ_SYMBOL_SIZE
        : RAPTORQ_SYMBOL_SIZE;
    this.batchTransport = offer.capabilities?.includes(BROWSER_BATCH_CAPABILITY)
      && offer.capabilities?.includes(BROWSER_SYMBOL_CAPABILITY);
    this.metrics = initialMetrics();
    this.adaptation = new BrowserAdaptationController();
    this.assembler = new SymbolAssembler();
    this.completedGenerations = new Set();
    this.receivedSymbolIDs = new Set();
    this.pendingCompletion = undefined;
    this.pendingRetry = undefined;
    this.pendingRetries = [];
    this.manifest = undefined;
    this.currentGenerationID = undefined;
    this.currentDecoder = undefined;
    this.completedBytes = 0;
    this.handshakeComplete = false;
    this.receiverPhase = 'handshake';
    this.roundID = 0;
    this.roundGenerationID = 0;
    this.cachedRoundFeedbackCode = undefined;
    this.manuallyPaused = false;
    this.backgroundPaused = false;
    this.lastDecodeAt = performance.now();
    this.finderGraceUntil = 0;
    this.decodeWindowStartedAt = performance.now();
    this.decodedFrameCount = 0;
    this.startedAt = performance.now();
    this.roundStats = undefined;
    this.roundFragmentKeys = new Set();
    this.lastRoundSummary = undefined;
    this.diagnostics = [];
  }

  async initialize() {
    await this.store.initialize();
    const metadata = await this.store.loadMetadata();
    const reusable = metadata?.sessionID === this.offer.sessionID
      && metadata?.senderPublicKey === this.offer.publicKey
      && metadata?.privateKey;
    this.cipher = new BrowserSessionCipher(
      this.offer,
      reusable ? base64ToBytes(metadata.privateKey) : undefined
    );
    if (reusable) {
      this.cipher.localSequence = metadata.nextControlSequence ?? 0;
      this.cipher.lastRemoteSequence = this.offer.detail === 'resume'
        ? undefined
        : metadata.lastRemoteSequence;
      this.completedGenerations = new Set(metadata.completedGenerations ?? []);
      this.completedBytes = metadata.completedBytes ?? 0;
      this.profileID = ['S0', 'P0', 'P1'].includes(metadata.selectedProfileID)
        ? metadata.selectedProfileID
        : this.profileID;
      this.adaptation = new BrowserAdaptationController(this.profileID);
      if (metadata.manifest) this.manifest = validateManifest(metadata.manifest, this.offer.sessionID);
      this.pendingRetries = metadata.pendingRetries ?? [];
      this.pendingRetry = this.pendingRetries[0];
      this.pendingCompletion = metadata.pendingCompletion;
      this.roundID = metadata.roundID ?? 0;
      this.roundGenerationID = metadata.roundGenerationID ?? 0;
      this.cachedRoundFeedbackCode = metadata.cachedRoundFeedbackCode;
      this.lastRoundSummary = metadata.lastRoundSummary;
      this.diagnostics = Array.isArray(metadata.diagnostics) ? metadata.diagnostics.slice(-200) : [];
    }
    let restoredState = metadata?.state;
    if (reusable
        && restoredState === 'verifying'
        && this.manifest
        && this.completedGenerations.size >= this.manifest.generationCount + 1) {
      this.state = 'verifying';
      this.receiverPhase = metadata.receiverPhase ?? 'receiving';
      this.handshakeComplete = metadata.handshakeComplete === true;
      await this.finalize();
      restoredState = this.state;
    }
    if (reusable
        && restoredState === 'complete'
        && this.manifest
        && this.completedBytes === this.manifest.fileSize
        && this.offer.detail !== 'resume') {
      this.state = 'verifying';
      this.receiverPhase = metadata.receiverPhase ?? 'receiving';
      this.handshakeComplete = metadata.handshakeComplete === true;
      await this.finalize(true);
      restoredState = this.state;
    }
    const alreadyComplete = reusable
      && restoredState === 'complete'
      && this.manifest
      && this.completedBytes === this.manifest.fileSize;
    const canContinueWithoutHandshake = reusable
      && metadata.handshakeComplete === true
      && this.offer.detail !== 'resume';
    this.state = alreadyComplete
      ? 'complete'
      : canContinueWithoutHandshake
        ? restoredState ?? 'transferring'
        : 'keyExchange';
    this.receiverPhase = restoredState === 'failed'
      ? 'feedbackReady'
      : this.offer.detail === 'resume'
      ? 'handshake'
      : alreadyComplete
        ? metadata.receiverPhase ?? 'receiving'
        : canContinueWithoutHandshake
        ? metadata.receiverPhase ?? 'receiving'
        : 'handshake';
    this.handshakeComplete = (alreadyComplete && this.offer.detail !== 'resume')
      || canContinueWithoutHandshake;
    this.recordDiagnostic('receiver-initialized', {
      reusable,
      symbolSize: this.symbolSize,
      batchTransport: this.batchTransport,
      storageMode: this.store.storageMode ?? 'unknown'
    });
    await this.persist();
    if (this.receiverPhase === 'feedbackReady') {
      this.emitUpdate();
      return this.feedbackCode();
    }
    if (canContinueWithoutHandshake) {
      this.emitUpdate();
      return undefined;
    }
    const answer = this.cipher.createAnswer(this.profileID, reusable ? 'resume-web' : 'web-receiver');
    await this.persist();
    this.emitUpdate();
    return encodeControlCode(answer);
  }

  async prepareDecoder() {
    await initializeRaptorQ();
  }

  async acceptControl(message) {
    if (message.kind === 'confirm' && !this.handshakeComplete) {
      if (message.transcriptHash !== bytesToBase64(this.cipher.transcriptHash)) {
        throw new Error('Handshake transcript verification failed');
      }
      this.cipher.verify(message);
      this.handshakeComplete = true;
      this.receiverPhase = 'receiving';
      if (this.state !== 'complete') this.state = 'calibrating';
      this.lastDecodeAt = performance.now();
      this.finderGraceUntil = this.lastDecodeAt + 3_000;
      this.startRoundStats(this.roundID + 1, this.metrics.generationID);
      this.recordDiagnostic('handshake-complete', {
        profileID: this.profileID,
        symbolSize: this.symbolSize,
        batchTransport: this.batchTransport
      });
      try {
        await this.persist();
      } catch (error) {
        await this.markFailed(error);
      }
      this.emitUpdate();
      return true;
    }
    if (message.kind === 'calibration' && this.handshakeComplete) {
      if (this.state === 'verifying') return false;
      this.cipher.verify(message);
      const boundary = parseRoundBoundaryDetail(message.detail);
      if (boundary) {
        this.finishRound(boundary);
        this.roundID = boundary.roundID;
        this.roundGenerationID = boundary.generationID;
        this.cachedRoundFeedbackCode = undefined;
        this.receiverPhase = 'feedbackReady';
        this.metrics.finderVisible = true;
        if (this.state !== 'complete' && this.state !== 'failed') this.state = 'reacquiring';
        try {
          await this.persist();
        } catch (error) {
          await this.markFailed(error);
        }
        this.emitUpdate();
        return true;
      }
      if (this.state === 'complete' || this.state === 'failed') return false;
      const ready = parseRoundReadyDetail(message.detail);
      if (ready) {
        this.roundID = ready.roundID;
        this.roundGenerationID = ready.generationID;
        if (this.metrics.generationID !== ready.generationID) {
          this.metrics.generationID = ready.generationID;
          this.metrics.receivedRank = 0;
        }
        this.startRoundStats(ready.roundID, ready.generationID);
      }
      this.receiverPhase = 'receiving';
      this.metrics.finderVisible = true;
      this.state = 'calibrating';
      this.lastDecodeAt = performance.now();
      this.finderGraceUntil = this.lastDecodeAt + 1_000;
      try {
        await this.persist();
      } catch (error) {
        await this.markFailed(error);
      }
      this.emitUpdate();
      return true;
    }
    return false;
  }

  async acceptFrame(frame) {
    if (!this.handshakeComplete
        || this.receiverPhase !== 'receiving'
        || this.state === 'complete'
        || this.state === 'failed'
        || this.state === 'verifying'
        || frame.sessionID.toUpperCase() !== this.offer.sessionID.toUpperCase()) return;
    if (![0, 1, 4].includes(frame.profileID)
        || frame.generationLength <= 0
        || frame.generationLength > MAX_ENCRYPTED_GENERATION_LENGTH) {
      throw new Error('Optical frame is outside browser receiver capabilities');
    }
    if (this.completedGenerations.has(frame.generationID)) {
      this.pendingCompletion = frame.generationID;
      return;
    }
    if (this.currentGenerationID !== frame.generationID) {
      this.resetDecoder();
      this.currentGenerationID = frame.generationID;
      this.currentDecoder = new BrowserRaptorQDecoder(frame.generationLength, this.symbolSize);
      this.metrics.generationID = frame.generationID;
      this.metrics.receivedRank = 0;
      this.pendingCompletion = undefined;
      this.pendingRetry = undefined;
    }
    if (!this.roundStats) this.startRoundStats(this.roundID + 1, frame.generationID);
    this.roundStats.generationID = frame.generationID;
    this.roundStats.sourceSymbolCount = Math.ceil(frame.generationLength / this.symbolSize);
    if ((frame.flags & ~OPTICAL_SYMBOL_BATCH_FLAG) !== 0) {
      throw new Error('Optical frame uses unsupported flags');
    }
    const fragmentKey = `${frame.generationID}:${frame.symbolID}:${frame.fragmentIndex}`;
    if (this.roundFragmentKeys.has(fragmentKey)) {
      this.roundStats.duplicateFragments += 1;
    } else {
      this.roundFragmentKeys.add(fragmentKey);
      this.roundStats.uniqueFragments += 1;
    }
    let symbols;
    if ((frame.flags & OPTICAL_SYMBOL_BATCH_FLAG) !== 0) {
      if (!this.batchTransport
          || frame.fragmentIndex !== 0
          || frame.fragmentCount !== 1) {
        throw new Error('Invalid batched optical frame metadata');
      }
      symbols = decodeSymbolBatch(frame.payload);
      if (symbols[0].symbolID !== frame.symbolID) {
        throw new Error('Batched optical frame identity mismatch');
      }
    } else {
      const packet = this.assembler.add(frame);
      if (!packet) return;
      symbols = [{ symbolID: frame.symbolID, packet }];
    }
    for (const symbol of symbols) {
      if (this.receivedSymbolIDs.has(symbol.symbolID)) continue;
      this.receivedSymbolIDs.add(symbol.symbolID);
      this.roundStats.completedSymbols += 1;
      this.metrics.generationID = frame.generationID;
      this.metrics.receivedRank = this.receivedSymbolIDs.size;
      const recovered = this.currentDecoder.add(symbol.packet);
      if (!recovered) continue;
      try {
        let plaintext;
        try {
          plaintext = this.cipher.openGeneration(recovered, frame.generationID);
        } catch (error) {
          throw new RetryableGenerationError('Generation authentication failed', { cause: error });
        }
        await this.commitGeneration(plaintext, frame.generationID);
        return;
      } catch (error) {
        if (error instanceof RetryableGenerationError) {
          this.queueGenerationRetry(frame.generationID);
        } else {
          await this.markFailed(error);
        }
        throw error;
      }
    }
  }

  recordDecode({
    success,
    latencyMilliseconds,
    colorConfidence,
    finderVisible,
    queueDepth = 0,
    errorCategory = 'other',
    errorMessage,
    geometry
  }) {
    const alpha = 0.2;
    this.metrics.frameSuccessRate = this.metrics.frameSuccessRate * (1 - alpha) + (success ? 1 : 0) * alpha;
    this.metrics.crcFailureRate = this.metrics.crcFailureRate * (1 - alpha) + (success ? 0 : 1) * alpha;
    this.metrics.shardLossRate = this.metrics.crcFailureRate;
    this.metrics.decodeP95Milliseconds = Math.max(
      latencyMilliseconds,
      this.metrics.decodeP95Milliseconds * 0.95
    );
    this.metrics.colorConfidence = this.metrics.colorConfidence * (1 - alpha) + colorConfidence * alpha;
    this.metrics.finderVisible = finderVisible || performance.now() < this.finderGraceUntil;
    this.metrics.queueDepth = queueDepth;
    if (this.roundStats) {
      this.roundStats.attemptedFrames += 1;
      this.roundStats.latencySamples.push(latencyMilliseconds);
      if (this.roundStats.latencySamples.length > 1_200) this.roundStats.latencySamples.shift();
      if (geometry) {
        const candidateCount = Number(geometry.candidateCount ?? 0);
        const componentCount = Number(geometry.componentCount ?? 0);
        const areaFraction = Number(geometry.areaFraction ?? 0);
        const modulePixels = Number(geometry.modulePixels ?? 0);
        this.roundStats.geometrySamples += 1;
        this.roundStats.candidateCountTotal += candidateCount;
        this.roundStats.candidateCountMaximum = Math.max(
          this.roundStats.candidateCountMaximum,
          candidateCount
        );
        this.roundStats.componentCountTotal += componentCount;
        this.roundStats.areaFractionTotal += areaFraction;
        this.roundStats.modulePixelsTotal += modulePixels;
        if (modulePixels > 0) {
          this.roundStats.modulePixelsMinimum = Math.min(
            this.roundStats.modulePixelsMinimum,
            modulePixels
          );
        }
        if (geometry.orientation !== undefined) {
          const orientationKey = `${geometry.orientation}${geometry.mirrored ? 'M' : ''}`;
          this.roundStats.orientationCounts[orientationKey]
            = (this.roundStats.orientationCounts[orientationKey] ?? 0) + 1;
        }
        if (geometry.corners) this.roundStats.lastCorners = geometry.corners;
      }
      if (success) {
        this.roundStats.decodedFrames += 1;
      } else if (errorCategory === 'finder') {
        this.roundStats.finderFailures += 1;
      } else if (errorCategory === 'geometry') {
        this.roundStats.geometryFailures += 1;
      } else if (errorCategory === 'checksum') {
        this.roundStats.checksumFailures += 1;
      } else if (errorCategory === 'profile') {
        this.roundStats.profileFailures += 1;
      } else {
        this.roundStats.otherFailures += 1;
      }
      if (!success && this.roundStats.failureSamples.length < 12) {
        this.roundStats.failureSamples.push({
          category: errorCategory,
          message: errorMessage ?? '',
          candidateCount: geometry?.candidateCount ?? 0,
          componentCount: geometry?.componentCount ?? 0,
          areaFraction: geometry?.areaFraction ?? 0,
          modulePixels: geometry?.modulePixels ?? 0,
          orientation: geometry?.orientation,
          mirrored: geometry?.mirrored
        });
      }
    }
    if (success) {
      this.decodedFrameCount += 1;
      this.lastDecodeAt = performance.now();
      this.finderGraceUntil = 0;
    }
    const now = performance.now();
    if (now - this.decodeWindowStartedAt >= 1000) {
      this.metrics.decodeFPS = this.decodedFrameCount * 1000 / (now - this.decodeWindowStartedAt);
      this.decodedFrameCount = 0;
      this.decodeWindowStartedAt = now;
    }
  }

  recordControlScan({ success, latencyMilliseconds }) {
    if (!this.roundStats) return;
    this.roundStats.controlScanAttempts += 1;
    if (success) this.roundStats.controlScanSuccesses += 1;
    this.roundStats.controlScanMilliseconds += latencyMilliseconds;
  }

  markFinderLostIfNeeded(now = performance.now()) {
    if (this.handshakeComplete && now >= this.finderGraceUntil && now - this.lastDecodeAt > 500) {
      this.metrics.finderVisible = false;
    }
  }

  async feedbackCode() {
    if (!this.handshakeComplete) throw new Error('Secure session is not established');
    if (this.receiverPhase === 'feedbackReady') {
      if (this.cachedRoundFeedbackCode) return this.cachedRoundFeedbackCode;
      let kind = 'feedback';
      let detail;
      if (this.state === 'failed') {
        kind = 'failure';
        detail = this.failureMessage ?? 'receiver-failed';
      } else if (this.state === 'complete') {
        kind = 'complete';
        detail = `sha256-verified-web:${this.roundID}:${this.roundGenerationID}`;
      } else {
        const decision = this.adaptation.evaluate(this.adaptationMetrics(true));
        this.profileID = decision.profileID;
        detail = this.pendingRetry !== undefined
          ? `round-retry:${this.pendingRetry}:${this.roundID}`
          : this.pendingCompletion === this.roundGenerationID
            ? `round-complete:${this.pendingCompletion}:${this.roundID}`
            : `round-repair:${this.roundGenerationID}:${this.metrics.receivedRank}:${this.roundID}`;
        this.state = 'reacquiring';
      }
      this.recordDiagnostic('feedback-generated', {
        kind,
        detail,
        profileID: this.profileID,
        roundID: this.roundID,
        generationID: this.roundGenerationID,
        receivedRank: this.metrics.receivedRank,
        diagnosis: this.lastRoundSummary?.diagnosis
      });
      this.cachedRoundFeedbackCode = encodeControlCode(this.cipher.createControl(kind, {
        requestedProfileID: this.profileID,
        metrics: this.metrics,
        detail
      }));
      try {
        await this.persist();
      } catch (error) {
        if (this.state !== 'failed') throw error;
      }
      this.emitUpdate();
      return this.cachedRoundFeedbackCode;
    }
    if (this.state === 'failed') {
      return encodeControlCode(this.cipher.createControl('failure', { detail: this.failureMessage ?? 'receiver-failed' }));
    }
    if (this.state === 'complete') {
      return encodeControlCode(this.cipher.createControl('complete', {
        detail: `sha256-verified-web:${this.roundID}:${this.roundGenerationID}`
      }));
    }
    if (this.manuallyPaused || this.backgroundPaused) {
      this.state = 'reacquiring';
      await this.persist();
      return encodeControlCode(this.cipher.createControl('pause', {
        requestedProfileID: this.profileID,
        metrics: this.metrics,
        detail: this.backgroundPaused ? 'browser-background' : 'manual-pause'
      }));
    }
    this.markFinderLostIfNeeded();
    const decision = this.adaptation.evaluate(this.adaptationMetrics(false));
    this.profileID = decision.profileID;
    this.state = decision.shouldPause ? 'reacquiring' : 'transferring';
    const detail = this.pendingRetry !== undefined
      ? `generation-retry:${this.pendingRetry}`
      : this.pendingCompletion !== undefined
        ? `generation-complete:${this.pendingCompletion}`
        : decision.reason;
    const code = encodeControlCode(this.cipher.createControl(decision.shouldPause ? 'pause' : 'feedback', {
      requestedProfileID: this.profileID,
      metrics: this.metrics,
      detail
    }));
    await this.persist();
    this.emitUpdate();
    return code;
  }

  async setPaused(paused, background = false) {
    if (this.state === 'complete' || this.state === 'failed') return;
    if (background) this.backgroundPaused = paused;
    else this.manuallyPaused = paused;
    if (!paused
        && !this.manuallyPaused
        && !this.backgroundPaused
        && this.receiverPhase === 'receiving'
        && this.state !== 'verifying') {
      this.metrics.finderVisible = true;
      this.lastDecodeAt = performance.now();
      this.state = 'transferring';
    }
    await this.persist();
    this.emitUpdate();
  }

  async resumeRoundReception() {
    if (this.receiverPhase !== 'feedbackReady' || this.state === 'complete' || this.state === 'failed') return false;
    this.cachedRoundFeedbackCode = undefined;
    this.receiverPhase = 'receiving';
    this.state = 'transferring';
    this.metrics.finderVisible = true;
    this.lastDecodeAt = performance.now();
    this.finderGraceUntil = this.lastDecodeAt + 4_000;
    this.startRoundStats(this.roundID + 1, this.roundGenerationID);
    this.recordDiagnostic('round-resumed', {
      roundID: this.roundID + 1,
      generationID: this.roundGenerationID,
      rankStart: this.metrics.receivedRank,
      profileID: this.profileID
    });
    await this.persist();
    this.emitUpdate();
    return true;
  }

  snapshot() {
    const total = this.manifest?.fileSize ?? 0;
    const elapsedSeconds = Math.max(0.1, (performance.now() - this.startedAt) / 1000);
    return {
      sessionID: this.offer.sessionID,
      state: this.state,
      receiverPhase: this.receiverPhase,
      roundID: this.roundID,
      roundGenerationID: this.roundGenerationID,
      profileID: this.profileID,
      targetFPS: (PROFILES.find((candidate) => candidate.id === this.profileID) ?? PROFILES[0]).fps,
      symbolSize: this.symbolSize,
      batchTransport: this.batchTransport,
      manifest: this.manifest,
      completedBytes: this.completedBytes,
      progressFraction: total > 0 ? Math.min(1, this.completedBytes / total) : 0,
      throughputMbps: this.completedBytes * 8 / elapsedSeconds / 1_000_000,
      metrics: { ...this.metrics },
      currentRoundStats: this.publicRoundStats(this.roundStats),
      lastRoundSummary: this.lastRoundSummary,
      diagnosis: this.lastRoundSummary?.diagnosis,
      failureMessage: this.failureMessage
    };
  }

  diagnosticReport() {
    return {
      exportedAt: new Date().toISOString(),
      protocolVersion: PROTOCOL_VERSION,
      sessionID: this.offer.sessionID,
      state: this.state,
      receiverPhase: this.receiverPhase,
      profileID: this.profileID,
      symbolSize: this.symbolSize,
      batchTransport: this.batchTransport,
      storageMode: this.store.storageMode ?? 'unknown',
      manifest: this.manifest ? {
        fileName: this.manifest.fileName,
        fileSize: this.manifest.fileSize,
        generationCount: this.manifest.generationCount
      } : undefined,
      completedGenerations: [...this.completedGenerations].sort((left, right) => left - right),
      completedBytes: this.completedBytes,
      metrics: { ...this.metrics },
      currentRoundStats: this.publicRoundStats(this.roundStats),
      lastRoundSummary: this.lastRoundSummary,
      diagnostics: [...this.diagnostics],
      userAgent: globalThis.navigator?.userAgent
    };
  }

  async download() {
    if (this.state !== 'complete' || !this.manifest) throw new Error('The ZIP is not verified yet');
    await this.store.download(this.manifest.fileName);
  }

  async commitGeneration(plaintext, generationID) {
    const digest = sha256(plaintext);
    if (generationID === 0) {
      const rawManifest = JSON.parse(textDecoder.decode(plaintext));
      this.manifest = validateManifest(rawManifest, this.offer.sessionID);
      await this.store.preparePartialFile(this.manifest.fileSize, false);
    } else {
      if (!this.manifest || generationID > this.manifest.generationCount) {
        throw new Error('ZIP data arrived before a valid manifest');
      }
      const hashIndex = generationID - 1;
      const offset = hashIndex * this.manifest.generationSize;
      const expectedLength = Math.min(this.manifest.generationSize, this.manifest.fileSize - offset);
      if (plaintext.length !== expectedLength
          || !equalBytes(digest, this.manifest.generationSHA256Bytes[hashIndex])) {
        throw new RetryableGenerationError('Generation SHA-256 does not match the encrypted manifest');
      }
      await this.store.writeGeneration(plaintext, hashIndex);
      this.completedBytes = Math.min(
        this.manifest.fileSize,
        generationID * this.manifest.generationSize
      );
    }
    this.completedGenerations.add(generationID);
    this.pendingRetries = this.pendingRetries.filter((candidate) => candidate !== generationID);
    this.pendingRetry = this.pendingRetries[0];
    this.pendingCompletion = this.pendingRetry === undefined ? generationID : undefined;
    this.state = 'transferring';
    this.resetDecoder();
    await this.persist();
    if (this.manifest
        && this.completedGenerations.size >= this.manifest.generationCount + 1) {
      await this.finalize();
    }
    this.emitUpdate();
  }

  async finalize(preserveCachedCompletion = false) {
    try {
      this.state = 'verifying';
      await this.persist();
      this.emitUpdate();
      const digest = await this.store.sha256();
      if (!equalBytes(digest, this.manifest.fileSHA256Bytes)) {
        const mismatched = await this.store.mismatchedGenerations(this.manifest);
        if (mismatched.length > 0) {
          for (const generationID of mismatched) this.completedGenerations.delete(generationID);
          this.pendingRetries = mismatched;
          this.pendingRetry = this.pendingRetries[0];
          this.pendingCompletion = undefined;
          this.cachedRoundFeedbackCode = undefined;
          this.completedBytes = Math.max(0, (mismatched[0] - 1) * this.manifest.generationSize);
          this.state = 'transferring';
          await this.persist();
          return;
        }
        await this.markFailed(new Error('Final SHA-256 verification failed'));
        return;
      }
      this.completedBytes = this.manifest.fileSize;
      this.state = 'complete';
      if (!preserveCachedCompletion) this.cachedRoundFeedbackCode = undefined;
      await this.persist();
    } catch (error) {
      await this.markFailed(error);
    }
  }

  resetDecoder() {
    this.currentDecoder?.free();
    this.currentDecoder = undefined;
    this.currentGenerationID = undefined;
    this.receivedSymbolIDs.clear();
    this.assembler.reset();
  }

  queueGenerationRetry(generationID) {
    this.pendingRetries = [
      generationID,
      ...this.pendingRetries.filter((candidate) => candidate !== generationID)
    ];
    this.pendingRetry = generationID;
    this.pendingCompletion = undefined;
    this.resetDecoder();
  }

  async markFailed(error) {
    this.failureMessage = error?.message ?? String(error);
    this.state = 'failed';
    this.receiverPhase = 'feedbackReady';
    this.cachedRoundFeedbackCode = undefined;
    this.pendingCompletion = undefined;
    this.pendingRetry = undefined;
    this.pendingRetries = [];
    this.resetDecoder();
    try {
      await this.persist();
    } catch {
      // Keep the authenticated failure QR available even when storage itself failed.
    }
    this.emitUpdate();
  }

  async persist() {
    await this.store.saveMetadata({
      senderPublicKey: this.offer.publicKey,
      privateKey: this.cipher?.exportPrivateKey(),
      nextControlSequence: this.cipher?.localSequence ?? 0,
      lastRemoteSequence: this.cipher?.lastRemoteSequence,
      selectedProfileID: this.profileID,
      state: this.state,
      manifest: this.manifest ? {
        protocolVersion: this.manifest.protocolVersion,
        sessionID: this.manifest.sessionID,
        fileName: this.manifest.fileName,
        fileSize: this.manifest.fileSize,
        fileSHA256: this.manifest.fileSHA256,
        generationSHA256: this.manifest.generationSHA256,
        generationSize: this.manifest.generationSize,
        generationCount: this.manifest.generationCount,
        createdAt: this.manifest.createdAt
      } : undefined,
      completedGenerations: [...this.completedGenerations].sort((left, right) => left - right),
      completedBytes: this.completedBytes,
      handshakeComplete: this.handshakeComplete,
      pendingRetries: this.pendingRetries,
      pendingCompletion: this.pendingCompletion,
      cachedRoundFeedbackCode: this.cachedRoundFeedbackCode,
      receiverPhase: this.receiverPhase,
      roundID: this.roundID,
      roundGenerationID: this.roundGenerationID,
      symbolSize: this.symbolSize,
      lastRoundSummary: this.lastRoundSummary,
      diagnostics: this.diagnostics.slice(-200),
      failureMessage: this.failureMessage
    });
  }

  startRoundStats(roundID, generationID) {
    const rankStart = generationID === this.metrics.generationID ? this.metrics.receivedRank : 0;
    this.roundStats = makeRoundStats(roundID, generationID, rankStart);
    this.roundFragmentKeys.clear();
  }

  finishRound(boundary) {
    const stats = this.roundStats ?? makeRoundStats(
      boundary.roundID,
      boundary.generationID,
      this.metrics.receivedRank
    );
    const endedAtMonotonic = performance.now();
    const durationMilliseconds = Math.max(1, endedAtMonotonic - stats.startedAtMonotonic);
    const durationSeconds = durationMilliseconds / 1000;
    const profile = PROFILES.find((candidate) => candidate.id === this.profileID) ?? PROFILES[0];
    const sourceSymbolCount = stats.sourceSymbolCount
      || (this.currentDecoder ? Math.ceil((this.currentDecoder.transferLength ?? 0) / this.symbolSize) : 0);
    const rankEnd = this.metrics.receivedRank;
    const summary = {
      roundID: boundary.roundID,
      generationID: boundary.generationID,
      startedAt: stats.startedAt,
      endedAt: new Date().toISOString(),
      durationMilliseconds: Math.round(durationMilliseconds),
      profileID: this.profileID,
      targetFPS: profile.fps,
      symbolSize: this.symbolSize,
      sourceSymbolCount,
      rankStart: stats.rankStart,
      rankEnd,
      rankGained: Math.max(0, rankEnd - stats.rankStart),
      rankDeficit: Math.max(0, sourceSymbolCount - rankEnd),
      attemptedFrames: stats.attemptedFrames,
      decodedFrames: stats.decodedFrames,
      frameSuccessRate: stats.attemptedFrames > 0 ? stats.decodedFrames / stats.attemptedFrames : 0,
      attemptedFPS: stats.attemptedFrames / durationSeconds,
      decodedFPS: stats.decodedFrames / durationSeconds,
      captureCoverage: Math.min(1, stats.attemptedFrames / Math.max(1, profile.fps * durationSeconds)),
      uniqueFragments: stats.uniqueFragments,
      duplicateFragments: stats.duplicateFragments,
      completedSymbols: stats.completedSymbols,
      symbolsPerDecodedFrame: stats.decodedFrames > 0
        ? stats.completedSymbols / stats.decodedFrames
        : 0,
      controlScanAttempts: stats.controlScanAttempts,
      controlScanSuccesses: stats.controlScanSuccesses,
      controlScanMilliseconds: Math.round(stats.controlScanMilliseconds),
      decodeP95Milliseconds: percentile95(stats.latencySamples),
      finderFailures: stats.finderFailures,
      geometryFailures: stats.geometryFailures,
      checksumFailures: stats.checksumFailures,
      profileFailures: stats.profileFailures,
      otherFailures: stats.otherFailures,
      senderNextSymbolID: boundary.nextSymbolID,
      ...geometrySummary(stats)
    };
    summary.diagnosis = roundDiagnosis(summary);
    this.lastRoundSummary = summary;
    this.recordDiagnostic('round-ended', summary);
    this.roundStats = undefined;
    this.roundFragmentKeys.clear();
  }

  publicRoundStats(stats) {
    if (!stats) return undefined;
    const durationMilliseconds = Math.max(1, performance.now() - stats.startedAtMonotonic);
    return {
      roundID: stats.roundID,
      generationID: stats.generationID,
      durationMilliseconds: Math.round(durationMilliseconds),
      sourceSymbolCount: stats.sourceSymbolCount,
      rankStart: stats.rankStart,
      rankNow: this.metrics.receivedRank,
      attemptedFrames: stats.attemptedFrames,
      decodedFrames: stats.decodedFrames,
      frameSuccessRate: stats.attemptedFrames > 0 ? stats.decodedFrames / stats.attemptedFrames : 0,
      uniqueFragments: stats.uniqueFragments,
      duplicateFragments: stats.duplicateFragments,
      completedSymbols: stats.completedSymbols,
      symbolsPerDecodedFrame: stats.decodedFrames > 0
        ? stats.completedSymbols / stats.decodedFrames
        : 0,
      finderFailures: stats.finderFailures,
      geometryFailures: stats.geometryFailures,
      checksumFailures: stats.checksumFailures,
      profileFailures: stats.profileFailures,
      otherFailures: stats.otherFailures,
      decodeP95Milliseconds: percentile95(stats.latencySamples),
      ...geometrySummary(stats)
    };
  }

  adaptationMetrics(forceFinderVisible) {
    if (!this.lastRoundSummary) {
      return forceFinderVisible ? { ...this.metrics, finderVisible: true } : this.metrics;
    }
    return {
      ...this.metrics,
      frameSuccessRate: this.lastRoundSummary.frameSuccessRate,
      shardLossRate: 1 - this.lastRoundSummary.frameSuccessRate,
      decodeFPS: this.lastRoundSummary.decodedFPS,
      decodeP95Milliseconds: this.lastRoundSummary.decodeP95Milliseconds,
      finderVisible: forceFinderVisible || this.lastRoundSummary.finderFailures < this.lastRoundSummary.attemptedFrames
    };
  }

  recordDiagnostic(name, fields = {}) {
    this.diagnostics.push({
      timestamp: new Date().toISOString(),
      name,
      sessionID: this.offer.sessionID,
      state: this.state,
      receiverPhase: this.receiverPhase,
      ...fields
    });
    if (this.diagnostics.length > 200) this.diagnostics.splice(0, this.diagnostics.length - 200);
  }

  emitUpdate() {
    this.dispatchEvent(new CustomEvent('update', { detail: this.snapshot() }));
  }
}
