const EXP = new Uint8Array(512);
const LOG = new Uint8Array(256);

let fieldValue = 1;
for (let index = 0; index < 255; index += 1) {
  EXP[index] = fieldValue;
  LOG[fieldValue] = index;
  fieldValue <<= 1;
  if ((fieldValue & 0x100) !== 0) fieldValue ^= 0x11d;
}
for (let index = 255; index < EXP.length; index += 1) {
  EXP[index] = EXP[index - 255];
}

function multiply(left, right) {
  if (left === 0 || right === 0) return 0;
  return EXP[LOG[left] + LOG[right]];
}

function power(value, exponent) {
  if (exponent === 0) return 1;
  if (value === 0) return 0;
  return EXP[(LOG[value] * exponent) % 255];
}

function inverse(value) {
  if (value === 0) throw new Error('Cannot invert zero in GF(256)');
  return EXP[255 - LOG[value]];
}

function identity(size) {
  return Array.from({ length: size }, (_, row) => {
    const output = new Uint8Array(size);
    output[row] = 1;
    return output;
  });
}

function invert(matrix) {
  const size = matrix.length;
  const left = matrix.map((row) => Uint8Array.from(row));
  const right = identity(size);
  for (let column = 0; column < size; column += 1) {
    if (left[column][column] === 0) {
      const swap = left.findIndex((row, index) => index > column && row[column] !== 0);
      if (swap < 0) throw new Error('Reed-Solomon matrix is singular');
      [left[column], left[swap]] = [left[swap], left[column]];
      [right[column], right[swap]] = [right[swap], right[column]];
    }
    const scale = inverse(left[column][column]);
    for (let index = 0; index < size; index += 1) {
      left[column][index] = multiply(left[column][index], scale);
      right[column][index] = multiply(right[column][index], scale);
    }
    for (let row = 0; row < size; row += 1) {
      if (row === column || left[row][column] === 0) continue;
      const factor = left[row][column];
      for (let index = 0; index < size; index += 1) {
        left[row][index] ^= multiply(factor, left[column][index]);
        right[row][index] ^= multiply(factor, right[column][index]);
      }
    }
  }
  return right;
}

function multiplyMatrices(left, right) {
  const rows = left.length;
  const columns = right[0].length;
  const inner = right.length;
  return Array.from({ length: rows }, (_, row) => {
    const output = new Uint8Array(columns);
    for (let column = 0; column < columns; column += 1) {
      let value = 0;
      for (let index = 0; index < inner; index += 1) {
        value ^= multiply(left[row][index], right[index][column]);
      }
      output[column] = value;
    }
    return output;
  });
}

function buildEncodingMatrix(shardCount, dataShardCount) {
  const vandermonde = Array.from({ length: shardCount }, (_, row) => {
    const output = new Uint8Array(dataShardCount);
    for (let column = 0; column < dataShardCount; column += 1) {
      output[column] = power(row, column);
    }
    return output;
  });
  return multiplyMatrices(vandermonde, invert(vandermonde.slice(0, dataShardCount)));
}

function codeShard(output, row, inputs, shardLength) {
  output.fill(0);
  for (let inputIndex = 0; inputIndex < inputs.length; inputIndex += 1) {
    const coefficient = row[inputIndex];
    if (coefficient === 0) continue;
    const input = inputs[inputIndex];
    for (let byteIndex = 0; byteIndex < shardLength; byteIndex += 1) {
      output[byteIndex] ^= multiply(coefficient, input[byteIndex]);
    }
  }
}

export function reconstructShards(shards, present, dataShardCount, shardLength) {
  const shardCount = shards.length;
  const presentCount = present.filter(Boolean).length;
  if (presentCount < dataShardCount) {
    throw new Error('Not enough Reed-Solomon shards to reconstruct the frame');
  }
  const matrix = buildEncodingMatrix(shardCount, dataShardCount);
  const selectedRows = [];
  const selectedShards = [];
  for (let index = 0; index < shardCount && selectedRows.length < dataShardCount; index += 1) {
    if (present[index]) {
      selectedRows.push(matrix[index]);
      selectedShards.push(shards[index]);
    }
  }
  const dataDecodeMatrix = invert(selectedRows);
  for (let index = 0; index < dataShardCount; index += 1) {
    if (present[index]) continue;
    codeShard(shards[index], dataDecodeMatrix[index], selectedShards, shardLength);
    present[index] = true;
  }
  const dataShards = shards.slice(0, dataShardCount);
  for (let index = dataShardCount; index < shardCount; index += 1) {
    if (present[index]) continue;
    codeShard(shards[index], matrix[index], dataShards, shardLength);
    present[index] = true;
  }
  return shards;
}

