import jsQR from 'jsqr';
import { PALETTE, PROFILES, profileByID, rawPayloadBytes } from './constants.js';
import { decodeGridEnvelope } from './grid-codec.js';
import { decodeOpticalFrame } from './optical-frame.js';

const INSET_MODULES = 18;
const FINDER_CENTER_MODULES = 8.5;
const MAX_CAPTURE_LONG_EDGE = 1_440;
const MIN_FRAME_AREA_FRACTION = 0.035;
const MIN_MODULE_PIXELS = 2.2;

class OpticalDecodeError extends Error {
  constructor(message, category, diagnostics = {}, options = {}) {
    super(message, options);
    this.name = 'OpticalDecodeError';
    this.category = category;
    this.diagnostics = diagnostics;
  }
}

function distance(left, right) {
  const red = left[0] - right[0];
  const green = left[1] - right[1];
  const blue = left[2] - right[2];
  return red * red + green * green + blue * blue;
}

function pointDistance(left, right) {
  return Math.hypot(left.x - right.x, left.y - right.y);
}

function quadrilateralArea(points) {
  let area = 0;
  for (let index = 0; index < points.length; index += 1) {
    const next = points[(index + 1) % points.length];
    area += points[index].x * next.y - next.x * points[index].y;
  }
  return Math.abs(area) / 2;
}

function sampleColor(imageData, point, radius = 1) {
  const { data, width, height } = imageData;
  const centerX = Math.max(0, Math.min(width - 1, Math.round(point.x)));
  const centerY = Math.max(0, Math.min(height - 1, Math.round(point.y)));
  let red = 0;
  let green = 0;
  let blue = 0;
  let count = 0;
  for (let offsetY = -radius; offsetY <= radius; offsetY += 1) {
    const y = Math.max(0, Math.min(height - 1, centerY + offsetY));
    for (let offsetX = -radius; offsetX <= radius; offsetX += 1) {
      const x = Math.max(0, Math.min(width - 1, centerX + offsetX));
      const offset = (y * width + x) * 4;
      red += data[offset];
      green += data[offset + 1];
      blue += data[offset + 2];
      count += 1;
    }
  }
  return [red / count, green / count, blue / count];
}

function luminance(color) {
  return color[0] * 0.299 + color[1] * 0.587 + color[2] * 0.114;
}

function adaptiveWhiteThreshold(imageData, sampleStep) {
  const histogram = new Uint32Array(256);
  let neutralCount = 0;
  const stride = Math.max(sampleStep * 4, 4);
  for (let y = Math.floor(stride / 2); y < imageData.height; y += stride) {
    for (let x = Math.floor(stride / 2); x < imageData.width; x += stride) {
      const offset = (y * imageData.width + x) * 4;
      const red = imageData.data[offset];
      const green = imageData.data[offset + 1];
      const blue = imageData.data[offset + 2];
      if (Math.max(red, green, blue) - Math.min(red, green, blue) > 54) continue;
      histogram[Math.round(red * 0.299 + green * 0.587 + blue * 0.114)] += 1;
      neutralCount += 1;
    }
  }
  if (neutralCount === 0) return 170;
  const target = neutralCount * 0.92;
  let accumulated = 0;
  let percentile = 255;
  for (let value = 0; value < histogram.length; value += 1) {
    accumulated += histogram[value];
    if (accumulated >= target) {
      percentile = value;
      break;
    }
  }
  return Math.max(158, Math.min(225, percentile - 8));
}

function scoreFinderCandidate(imageData, component) {
  const width = component.maxX - component.minX;
  const height = component.maxY - component.minY;
  const radius = Math.max(0, Math.floor(Math.min(width, height) / 45));
  let whiteTotal = 0;
  let whiteCount = 0;
  let darkTotal = 0;
  let darkCount = 0;
  let edgeMinimum = 255;
  for (let row = 0; row < 9; row += 1) {
    for (let column = 0; column < 9; column += 1) {
      const point = {
        x: component.minX + (column + 0.5) * width / 9,
        y: component.minY + (row + 0.5) * height / 9
      };
      const value = luminance(sampleColor(imageData, point, radius));
      const edge = row === 0 || column === 0 || row === 8 || column === 8;
      const core = row >= 3 && row <= 5 && column >= 3 && column <= 5;
      if (edge || core) {
        whiteTotal += value;
        whiteCount += 1;
        if (edge) edgeMinimum = Math.min(edgeMinimum, value);
      } else {
        darkTotal += value;
        darkCount += 1;
      }
    }
  }
  const whiteMean = whiteTotal / whiteCount;
  const darkMean = darkTotal / darkCount;
  const contrast = whiteMean - darkMean;
  const score = contrast / 255 + Math.min(0.25, Math.max(0, edgeMinimum - darkMean) / 510);
  return {
    ...component,
    x: component.minX + width / 2,
    y: component.minY + height / 2,
    whiteMean,
    darkMean,
    contrast,
    score
  };
}

function brightComponents(imageData) {
  const { data, width, height } = imageData;
  const sampleStep = Math.max(2, Math.round(Math.max(width, height) / 900));
  const gridWidth = Math.ceil(width / sampleStep);
  const gridHeight = Math.ceil(height / sampleStep);
  const threshold = adaptiveWhiteThreshold(imageData, sampleStep);
  const bright = new Uint8Array(gridWidth * gridHeight);
  for (let gridY = 0; gridY < gridHeight; gridY += 1) {
    const y = Math.min(height - 1, gridY * sampleStep + Math.floor(sampleStep / 2));
    for (let gridX = 0; gridX < gridWidth; gridX += 1) {
      const x = Math.min(width - 1, gridX * sampleStep + Math.floor(sampleStep / 2));
      const offset = (y * width + x) * 4;
      const red = data[offset];
      const green = data[offset + 1];
      const blue = data[offset + 2];
      const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);
      const value = red * 0.299 + green * 0.587 + blue * 0.114;
      if (value >= threshold && chroma <= 58) bright[gridY * gridWidth + gridX] = 1;
    }
  }

  const queue = new Int32Array(gridWidth * gridHeight);
  const components = [];
  for (let start = 0; start < bright.length; start += 1) {
    if (bright[start] !== 1) continue;
    let head = 0;
    let tail = 0;
    queue[tail++] = start;
    bright[start] = 2;
    let pixelCount = 0;
    let minGridX = gridWidth;
    let minGridY = gridHeight;
    let maxGridX = 0;
    let maxGridY = 0;
    while (head < tail) {
      const current = queue[head++];
      const gridY = Math.floor(current / gridWidth);
      const gridX = current - gridY * gridWidth;
      pixelCount += 1;
      minGridX = Math.min(minGridX, gridX);
      maxGridX = Math.max(maxGridX, gridX);
      minGridY = Math.min(minGridY, gridY);
      maxGridY = Math.max(maxGridY, gridY);
      for (let offsetY = -1; offsetY <= 1; offsetY += 1) {
        const neighborY = gridY + offsetY;
        if (neighborY < 0 || neighborY >= gridHeight) continue;
        for (let offsetX = -1; offsetX <= 1; offsetX += 1) {
          if (offsetX === 0 && offsetY === 0) continue;
          const neighborX = gridX + offsetX;
          if (neighborX < 0 || neighborX >= gridWidth) continue;
          const neighbor = neighborY * gridWidth + neighborX;
          if (bright[neighbor] !== 1) continue;
          bright[neighbor] = 2;
          queue[tail++] = neighbor;
        }
      }
    }
    const componentWidth = (maxGridX - minGridX + 1) * sampleStep;
    const componentHeight = (maxGridY - minGridY + 1) * sampleStep;
    const aspect = componentWidth / Math.max(1, componentHeight);
    const fill = pixelCount / Math.max(1, (maxGridX - minGridX + 1) * (maxGridY - minGridY + 1));
    if (pixelCount < 20
        || componentWidth < 14
        || componentHeight < 14
        || componentWidth > width * 0.24
        || componentHeight > height * 0.32
        || aspect < 0.45
        || aspect > 2.2
        || fill < 0.08
        || fill > 0.78) continue;
    components.push({
      minX: minGridX * sampleStep,
      minY: minGridY * sampleStep,
      maxX: Math.min(width, (maxGridX + 1) * sampleStep),
      maxY: Math.min(height, (maxGridY + 1) * sampleStep),
      pixelCount,
      fill
    });
  }
  return { components, sampleStep, threshold };
}

function orderCorners(points) {
  let topLeft;
  let topRight;
  let bottomRight;
  let bottomLeft;
  let minimumSum = Number.POSITIVE_INFINITY;
  let maximumSum = Number.NEGATIVE_INFINITY;
  let minimumDifference = Number.POSITIVE_INFINITY;
  let maximumDifference = Number.NEGATIVE_INFINITY;
  for (const point of points) {
    const sum = point.x + point.y;
    const difference = point.x - point.y;
    if (sum < minimumSum) { minimumSum = sum; topLeft = point; }
    if (sum > maximumSum) { maximumSum = sum; bottomRight = point; }
    if (difference > maximumDifference) { maximumDifference = difference; topRight = point; }
    if (difference < minimumDifference) { minimumDifference = difference; bottomLeft = point; }
  }
  const ordered = [topLeft, topRight, bottomRight, bottomLeft];
  return new Set(ordered).size === 4 ? ordered : undefined;
}

function isConvex(points) {
  let sign = 0;
  for (let index = 0; index < points.length; index += 1) {
    const current = points[index];
    const next = points[(index + 1) % points.length];
    const following = points[(index + 2) % points.length];
    const cross = (next.x - current.x) * (following.y - next.y)
      - (next.y - current.y) * (following.x - next.x);
    if (Math.abs(cross) < 1) return false;
    const currentSign = Math.sign(cross);
    if (sign !== 0 && currentSign !== sign) return false;
    sign = currentSign;
  }
  return true;
}

function selectFinderQuadrilateral(candidates, imageData) {
  const shortlisted = [...candidates]
    .sort((left, right) => right.score - left.score)
    .slice(0, 12);
  let best;
  for (let a = 0; a < shortlisted.length - 3; a += 1) {
    for (let b = a + 1; b < shortlisted.length - 2; b += 1) {
      for (let c = b + 1; c < shortlisted.length - 1; c += 1) {
        for (let d = c + 1; d < shortlisted.length; d += 1) {
          const selected = [shortlisted[a], shortlisted[b], shortlisted[c], shortlisted[d]];
          const ordered = orderCorners(selected);
          if (!ordered || !isConvex(ordered)) continue;
          const areaFraction = quadrilateralArea(ordered) / (imageData.width * imageData.height);
          if (areaFraction < MIN_FRAME_AREA_FRACTION) continue;
          const horizontal = (pointDistance(ordered[0], ordered[1]) + pointDistance(ordered[3], ordered[2])) / 2;
          const vertical = (pointDistance(ordered[0], ordered[3]) + pointDistance(ordered[1], ordered[2])) / 2;
          const aspect = horizontal / Math.max(1, vertical);
          if (aspect < 0.38 || aspect > 2.65) continue;
          const finderScore = selected.reduce((total, candidate) => total + candidate.score, 0);
          const score = finderScore + Math.min(0.9, areaFraction) * 1.5;
          if (!best || score > best.score) {
            best = { ordered, selected, areaFraction, imageAspectRatio: aspect, score };
          }
        }
      }
    }
  }
  return best;
}

function detectFrameGeometry(imageData) {
  const { components, sampleStep, threshold } = brightComponents(imageData);
  const candidates = components
    .map((component) => scoreFinderCandidate(imageData, component))
    .filter((candidate) => (
      candidate.contrast >= 38
      && candidate.whiteMean >= 145
      && candidate.score >= 0.18
    ));
  const baseDiagnostics = {
    finderVisible: candidates.length >= 4,
    candidateCount: candidates.length,
    componentCount: components.length,
    whiteThreshold: threshold,
    sampleStep
  };
  if (candidates.length < 4) {
    throw new OpticalDecodeError('Optical frame finder is not visible', 'finder', baseDiagnostics);
  }
  const selection = selectFinderQuadrilateral(candidates, imageData);
  if (!selection) {
    throw new OpticalDecodeError('Optical frame geometry is invalid', 'geometry', baseDiagnostics);
  }
  const corners = {
    topLeft: { x: selection.ordered[0].x, y: selection.ordered[0].y },
    topRight: { x: selection.ordered[1].x, y: selection.ordered[1].y },
    bottomRight: { x: selection.ordered[2].x, y: selection.ordered[2].y },
    bottomLeft: { x: selection.ordered[3].x, y: selection.ordered[3].y }
  };
  return {
    corners,
    diagnostics: {
      ...baseDiagnostics,
      areaFraction: selection.areaFraction,
      imageAspectRatio: selection.imageAspectRatio,
      corners,
      finderScores: selection.selected.map((candidate) => Number(candidate.score.toFixed(3)))
    }
  };
}

function orientPoint(point, orientation, mirrored) {
  let x = mirrored ? 1 - point.x : point.x;
  let y = point.y;
  if (orientation === 90) [x, y] = [1 - y, x];
  else if (orientation === 180) [x, y] = [1 - x, 1 - y];
  else if (orientation === 270) [x, y] = [y, 1 - x];
  return { x, y };
}

function orientedFinderCorners(corners, orientation, mirrored) {
  const physical = new Map([
    ['0,0', corners.topLeft],
    ['1,0', corners.topRight],
    ['1,1', corners.bottomRight],
    ['0,1', corners.bottomLeft]
  ]);
  return [
    { x: 0, y: 0 },
    { x: 1, y: 0 },
    { x: 1, y: 1 },
    { x: 0, y: 1 }
  ].map((point) => {
    const oriented = orientPoint(point, orientation, mirrored);
    return physical.get(`${oriented.x},${oriented.y}`);
  });
}

function squareToQuadrilateral(points) {
  const [topLeft, topRight, bottomRight, bottomLeft] = points;
  const dx1 = topRight.x - bottomRight.x;
  const dx2 = bottomLeft.x - bottomRight.x;
  const dx3 = topLeft.x - topRight.x + bottomRight.x - bottomLeft.x;
  const dy1 = topRight.y - bottomRight.y;
  const dy2 = bottomLeft.y - bottomRight.y;
  const dy3 = topLeft.y - topRight.y + bottomRight.y - bottomLeft.y;
  const denominator = dx1 * dy2 - dx2 * dy1;
  if (Math.abs(denominator) < 1e-6) {
    throw new OpticalDecodeError('Optical frame perspective is degenerate', 'geometry', { finderVisible: true });
  }
  const g = (dx3 * dy2 - dx2 * dy3) / denominator;
  const h = (dx1 * dy3 - dx3 * dy1) / denominator;
  return {
    a: topRight.x - topLeft.x + g * topRight.x,
    b: bottomLeft.x - topLeft.x + h * bottomLeft.x,
    c: topLeft.x,
    d: topRight.y - topLeft.y + g * topRight.y,
    e: bottomLeft.y - topLeft.y + h * bottomLeft.y,
    f: topLeft.y,
    g,
    h
  };
}

function project(projector, normalizedX, normalizedY) {
  const x = (normalizedX - projector.finderInsetX) / projector.finderSpanX;
  const y = (normalizedY - projector.finderInsetY) / projector.finderSpanY;
  const denominator = projector.g * x + projector.h * y + 1;
  return {
    x: (projector.a * x + projector.b * y + projector.c) / denominator,
    y: (projector.d * x + projector.e * y + projector.f) / denominator
  };
}

function projectorFor(profile, detected, orientation, mirrored, imageData) {
  const points = orientedFinderCorners(detected.corners, orientation, mirrored);
  const horizontal = (pointDistance(points[0], points[1]) + pointDistance(points[3], points[2])) / 2;
  const vertical = (pointDistance(points[0], points[3]) + pointDistance(points[1], points[2])) / 2;
  const totalColumns = profile.columns + INSET_MODULES * 2;
  const totalRows = profile.rows + INSET_MODULES * 2;
  const expectedAspect = (totalColumns - FINDER_CENTER_MODULES * 2)
    / (totalRows - FINDER_CENTER_MODULES * 2);
  const measuredAspect = horizontal / Math.max(1, vertical);
  const aspectError = Math.abs(Math.log(measuredAspect / expectedAspect));
  const modulePixels = Math.min(
    horizontal / (totalColumns - FINDER_CENTER_MODULES * 2),
    vertical / (totalRows - FINDER_CENTER_MODULES * 2)
  );
  const geometry = {
    ...detected.diagnostics,
    orientation,
    mirrored,
    expectedAspectRatio: expectedAspect,
    logicalAspectRatio: measuredAspect,
    aspectError,
    modulePixels,
    captureWidth: imageData.width,
    captureHeight: imageData.height
  };
  if (aspectError > 0.48 || modulePixels < MIN_MODULE_PIXELS) {
    throw new OpticalDecodeError('Optical frame geometry is invalid', 'geometry', geometry);
  }
  return {
    ...squareToQuadrilateral(points),
    finderInsetX: FINDER_CENTER_MODULES / totalColumns,
    finderInsetY: FINDER_CENTER_MODULES / totalRows,
    finderSpanX: 1 - FINDER_CENTER_MODULES * 2 / totalColumns,
    finderSpanY: 1 - FINDER_CENTER_MODULES * 2 / totalRows,
    geometry
  };
}

function calibratedPalette(imageData, projector, profile) {
  const totalColumns = profile.columns + INSET_MODULES * 2;
  const totalRows = profile.rows + INSET_MODULES * 2;
  const samples = Array.from({ length: 4 }, () => []);
  const radius = projector.geometry.modulePixels >= 5 ? 1 : 0;
  for (let index = 0; index < 8; index += 1) {
    const x = (INSET_MODULES + index * 3 + 1.5) / totalColumns;
    const y = 1 - (INSET_MODULES - 2) / totalRows;
    samples[index % 4].push(sampleColor(imageData, project(projector, x, y), radius));
  }
  return samples.map((values, index) => {
    if (values.length === 0) return PALETTE[index];
    return [0, 1, 2].map((channel) => (
      values.reduce((total, value) => total + value[channel], 0) / values.length
    ));
  });
}

function classifyDataError(error) {
  const message = `${error?.message ?? error}`.toLowerCase();
  if (message.includes('profile')) return 'profile';
  if (message.includes('checksum') || message.includes('crc') || message.includes('reed')) return 'checksum';
  return 'other';
}

function decodeProfile(imageData, detected, profile, orientation = 0, mirrored = false) {
  const projector = projectorFor(profile, detected, orientation, mirrored, imageData);
  const totalColumns = profile.columns + INSET_MODULES * 2;
  const totalRows = profile.rows + INSET_MODULES * 2;
  const palette = calibratedPalette(imageData, projector, profile);
  const output = new Uint8Array(rawPayloadBytes(profile));
  const paletteSize = profile.colorBits === 1 ? 2 : 4;
  const maximumDistance = 255 * 255 * 3;
  let confidenceTotal = 0;
  const cellCount = profile.columns * profile.rows;
  const radius = projector.geometry.modulePixels >= 5.5 ? 1 : 0;

  for (let cell = 0; cell < cellCount; cell += 1) {
    const column = cell % profile.columns;
    const row = Math.floor(cell / profile.columns);
    const normalizedX = (INSET_MODULES + column + 0.5) / totalColumns;
    const normalizedY = 1 - (INSET_MODULES + row + 0.5) / totalRows;
    const color = sampleColor(imageData, project(projector, normalizedX, normalizedY), radius);
    let symbol = 0;
    let nearestDistance = Number.POSITIVE_INFINITY;
    for (let index = 0; index < paletteSize; index += 1) {
      const candidateDistance = distance(color, palette[index]);
      if (candidateDistance < nearestDistance) {
        nearestDistance = candidateDistance;
        symbol = index;
      }
    }
    confidenceTotal += 1 - Math.min(1, Math.sqrt(nearestDistance / maximumDistance));
    const bitOffset = cell * profile.colorBits;
    const byteIndex = Math.floor(bitOffset / 8);
    const shift = 8 - profile.colorBits - (bitOffset % 8);
    output[byteIndex] |= symbol << shift;
  }

  try {
    const frame = decodeOpticalFrame(decodeGridEnvelope(output));
    const expectedProfileID = profile.wireID ?? PROFILES.findIndex((candidate) => candidate.id === profile.id);
    if (frame.profileID !== expectedProfileID) throw new Error('Optical frame profile mismatch');
    return {
      frame,
      profile,
      colorConfidence: confidenceTotal / cellCount,
      corners: detected.corners,
      geometry: projector.geometry,
      orientation,
      mirrored
    };
  } catch (error) {
    throw new OpticalDecodeError(
      error?.message ?? 'Unable to decode optical grid',
      classifyDataError(error),
      projector.geometry,
      { cause: error }
    );
  }
}

function transformCandidates(preferred) {
  const values = [];
  if (preferred) values.push(preferred);
  for (const mirrored of [false, true]) {
    for (const orientation of [0, 90, 180, 270]) {
      if (preferred?.orientation === orientation && preferred?.mirrored === mirrored) continue;
      values.push({ orientation, mirrored });
    }
  }
  return values;
}

function decodeImage(imageData, expectedProfileID, preferredTransform) {
  const detected = detectFrameGeometry(imageData);
  const expected = profileByID(expectedProfileID);
  const profiles = [expected, ...PROFILES.filter((profile) => profile !== expected)];
  const failures = [];
  for (const profile of profiles) {
    for (const transform of transformCandidates(preferredTransform)) {
      try {
        return decodeProfile(imageData, detected, profile, transform.orientation, transform.mirrored);
      } catch (error) {
        failures.push(error);
      }
    }
  }
  const preferredFailure = failures.find((error) => error.category === 'checksum')
    ?? failures.find((error) => error.category === 'profile')
    ?? failures.find((error) => error.category === 'other')
    ?? failures.at(-1);
  if (preferredFailure) {
    preferredFailure.diagnostics = {
      ...detected.diagnostics,
      ...preferredFailure.diagnostics,
      attemptedTransforms: failures.length
    };
    throw preferredFailure;
  }
  throw new OpticalDecodeError('Unable to decode optical grid', 'other', detected.diagnostics);
}

export function browserCameraConstraintCandidates() {
  return [
    {
      audio: false,
      video: {
        facingMode: { exact: 'environment' },
        width: { ideal: 1920 },
        height: { ideal: 1080 },
        frameRate: { ideal: 30, max: 30 }
      }
    },
    {
      audio: false,
      video: {
        facingMode: { ideal: 'environment' },
        width: { ideal: 1920 },
        height: { ideal: 1080 },
        frameRate: { ideal: 24, max: 30 }
      }
    }
  ];
}

export function browserCameraConstraints() {
  return browserCameraConstraintCandidates()[0];
}

function canRetryCameraConstraint(error) {
  return ['OverconstrainedError', 'NotFoundError'].includes(error?.name);
}

export class BrowserOpticalDecoder {
  constructor(video, canvas = document.createElement('canvas')) {
    this.video = video;
    this.canvas = canvas;
    this.context = canvas.getContext('2d', { alpha: false, willReadFrequently: true });
    this.stream = undefined;
    this.cameraStartAttempts = [];
    this.preferredTransform = undefined;
    this.lastCapture = undefined;
  }

  async startCamera(getUserMedia = navigator.mediaDevices?.getUserMedia?.bind(navigator.mediaDevices)) {
    if (!getUserMedia) throw new Error('Camera capture requires Safari over HTTPS');
    this.cameraStartAttempts = [];
    const candidates = browserCameraConstraintCandidates();
    for (let index = 0; index < candidates.length; index += 1) {
      const constraints = candidates[index];
      try {
        this.stream = await getUserMedia(constraints);
        this.cameraStartAttempts.push({ mode: index === 0 ? 'preferred' : 'compatible', success: true });
        this.video.srcObject = this.stream;
        this.video.playsInline = true;
        this.video.muted = true;
        await this.video.play();
        return;
      } catch (error) {
        this.cameraStartAttempts.push({
          mode: index === 0 ? 'preferred' : 'compatible',
          success: false,
          errorName: error?.name ?? 'Error',
          errorMessage: error?.message ?? ''
        });
        if (!canRetryCameraConstraint(error) || index === candidates.length - 1) throw error;
      }
    }
  }

  cameraDiagnostics() {
    const track = this.stream?.getVideoTracks?.()[0];
    return {
      attempts: this.cameraStartAttempts.map((attempt) => ({ ...attempt })),
      settings: track?.getSettings?.() ?? {},
      capture: this.lastCapture
    };
  }

  stopCamera() {
    for (const track of this.stream?.getTracks() ?? []) track.stop();
    this.stream = undefined;
    this.video.srcObject = null;
  }

  isCameraActive() {
    return this.stream?.getVideoTracks().some((track) => track.readyState === 'live') === true;
  }

  capture() {
    const sourceWidth = this.video.videoWidth;
    const sourceHeight = this.video.videoHeight;
    if (!sourceWidth || !sourceHeight) throw new Error('Camera frame is not ready');
    const scale = Math.min(1, MAX_CAPTURE_LONG_EDGE / Math.max(sourceWidth, sourceHeight));
    const width = Math.max(1, Math.round(sourceWidth * scale));
    const height = Math.max(1, Math.round(sourceHeight * scale));
    if (this.canvas.width !== width || this.canvas.height !== height) {
      this.canvas.width = width;
      this.canvas.height = height;
    }
    this.context.drawImage(this.video, 0, 0, width, height);
    this.lastCapture = { sourceWidth, sourceHeight, width, height, scale };
    return this.context.getImageData(0, 0, width, height);
  }

  scanControlCode(imageData = this.capture()) {
    return jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: 'attemptBoth' })?.data;
  }

  decode(expectedProfileID, imageData = this.capture()) {
    const result = decodeImage(imageData, expectedProfileID, this.preferredTransform);
    this.preferredTransform = { orientation: result.orientation, mirrored: result.mirrored };
    return result;
  }
}

export const opticalDecoderInternals = {
  decodeImage,
  decodeProfile,
  detectFrameGeometry,
  project,
  squareToQuadrilateral
};
