import initRaptorQ, { Decoder } from 'raptorq/raptorq.js';
import { RAPTORQ_SYMBOL_SIZE } from './constants.js';

let initialization;

export async function initializeRaptorQ() {
  initialization ??= initRaptorQ();
  await initialization;
}

export class BrowserRaptorQDecoder {
  constructor(transferLength, symbolSize = RAPTORQ_SYMBOL_SIZE) {
    this.transferLength = transferLength;
    this.symbolSize = symbolSize;
    this.decoder = Decoder.with_defaults(BigInt(transferLength), symbolSize);
  }

  add(packet) {
    return this.decoder.decode(packet);
  }

  free() {
    this.decoder?.free();
    this.decoder = undefined;
  }
}
